const CARDS_DATA = {"decks": [{"id": "cifras", "icon": "⚡", "name": "Cifras clave"}, {"id": "vision", "icon": "🎯", "name": "Visión global"}, {"id": "datos", "icon": "📊", "name": "Datos y pipeline"}, {"id": "metodo", "icon": "🧪", "name": "Metodología"}, {"id": "modelos", "icon": "🤖", "name": "Modelos"}, {"id": "estadistica", "icon": "📈", "name": "Estadística"}, {"id": "negocio", "icon": "💼", "name": "Negocio y sector"}, {"id": "etica", "icon": "⚖️", "name": "Ética y privacidad"}, {"id": "hostiles", "icon": "🔥", "name": "Preguntas hostiles"}, {"id": "frases", "icon": "🗣️", "name": "Cómo decirlo"}], "cards": [{"id": "g128", "deck": "cifras", "q": "¿Cuántas observaciones GPS?", "a": "61,273,298 observaciones.", "level": "basico", "crit": false, "idea": "61.27 millones."}, {"id": "g129", "deck": "cifras", "q": "¿Cuántos turnos?", "a": "106,699 turnos operativos segmentados.", "level": "basico", "crit": false, "idea": "106,699."}, {"id": "g130", "deck": "cifras", "q": "¿Cuántos eventos corporativos?", "a": "2,447 eventos registrados corporativamente.", "level": "basico", "crit": false, "idea": "2,447."}, {"id": "g131", "deck": "cifras", "q": "¿Cuántos eventos dentro del período GPS?", "a": "301 eventos.", "level": "basico", "crit": false, "idea": "301."}, {"id": "g132", "deck": "cifras", "q": "¿Cuántos eventos utilizables con cobertura confirmada?", "a": "54 eventos.", "level": "basico", "crit": false, "idea": "54."}, {"id": "g133", "deck": "cifras", "q": "¿Cuántos expertos?", "a": "Siete especialistas.", "level": "basico", "crit": false, "idea": "7."}, {"id": "g134", "deck": "cifras", "q": "¿Cuántas variables candidatas?", "a": "Catorce variables.", "level": "basico", "crit": false, "idea": "14."}, {"id": "g135", "deck": "cifras", "q": "¿Cuántas variables se construyeron?", "a": "Tres completamente y una parcialmente.", "level": "basico", "crit": false, "idea": "3 + 1 parcial."}, {"id": "g136", "deck": "cifras", "q": "¿Cuántas variables fueron sólidas en pertinencia?", "a": "Cuatro.", "level": "basico", "crit": false, "idea": "4."}, {"id": "g137", "deck": "cifras", "q": "¿Cuántos sesgos identificaron?", "a": "Cinco sesgos de evaluación.", "level": "basico", "crit": false, "idea": "5."}, {"id": "g138", "deck": "cifras", "q": "¿Cuántos chequeos de integridad?", "a": "41 de 41 conformes.", "level": "basico", "crit": false, "idea": "41/41."}, {"id": "g139", "deck": "cifras", "q": "¿Cuántos chequeos de exportación?", "a": "30 de 30 conformes.", "level": "basico", "crit": false, "idea": "30/30."}, {"id": "g140", "deck": "cifras", "q": "¿Cuántos defectos del pipeline corrigieron?", "a": "Trece defectos de procesamiento.", "level": "basico", "crit": false, "idea": "13."}, {"id": "g141", "deck": "cifras", "q": "¿Tamaño de ventana?", "a": "30 observaciones, equivalentes a 30 minutos.", "level": "basico", "crit": false, "idea": "30 min."}, {"id": "g142", "deck": "cifras", "q": "¿Paso de ventana?", "a": "15 observaciones, equivalentes a 15 minutos.", "level": "basico", "crit": false, "idea": "15 min."}, {"id": "g143", "deck": "cifras", "q": "¿Ventanas normales finales?", "a": "3,884,561.", "level": "basico", "crit": false, "idea": "3.884 millones."}, {"id": "g144", "deck": "cifras", "q": "¿Recall recurrente en P99.9?", "a": "31.5%, IC95% 20.4–44.4%.", "level": "basico", "crit": false, "idea": "31.5%."}, {"id": "g145", "deck": "cifras", "q": "¿Recall árboles en P99.9?", "a": "38.9%, IC95% 25.9–51.9%.", "level": "basico", "crit": false, "idea": "38.9%."}, {"id": "g146", "deck": "cifras", "q": "¿Alertas/día P99.9?", "a": "16.9 para recurrente y 15.9 para árboles.", "level": "basico", "crit": false, "idea": "≈16/día."}, {"id": "g147", "deck": "cifras", "q": "¿Recall árboles en P95 usado en permutación?", "a": "48.15%, aproximadamente 48.1%.", "level": "basico", "crit": false, "idea": "48.15%."}, {"id": "g148", "deck": "cifras", "q": "¿p empírico árboles?", "a": "0.032 con 30 repeticiones.", "level": "basico", "crit": false, "idea": "0.032."}, {"id": "g149", "deck": "cifras", "q": "¿p mínimo recurrente?", "a": "0.091 con 10 repeticiones; por eso es indicativo.", "level": "basico", "crit": false, "idea": "0.091."}, {"id": "g150", "deck": "cifras", "q": "¿Cuántas ventanas >15 min antes del evento?", "a": "Tres de 54, 5.6%.", "level": "basico", "crit": false, "idea": "3/54."}, {"id": "g151", "deck": "cifras", "q": "¿Mediana de anticipación en esas tres?", "a": "33.4 minutos.", "level": "basico", "crit": false, "idea": "33.4 min."}, {"id": "g152", "deck": "cifras", "q": "¿Coordenadas centinela?", "a": "10.52% de los registros.", "level": "basico", "crit": false, "idea": "10.52%."}, {"id": "g153", "deck": "cifras", "q": "¿Saltos extremos?", "a": "0.03% de observaciones, con valores de hasta 15,450 km.", "level": "basico", "crit": false, "idea": "0.03%; hasta 15,450 km."}, {"id": "g154", "deck": "cifras", "q": "¿Dispositivos que operan en múltiples ubicaciones?", "a": "33.9% opera en dos o más ubicaciones diferenciadas.", "level": "basico", "crit": false, "idea": "33.9%."}, {"id": "g155", "deck": "cifras", "q": "¿Qué horizonte temporal usa la simulación operativa?", "a": "Los últimos 30 días del período como tramo no observado.", "level": "basico", "crit": false, "idea": "30 días."}, {"id": "g1", "deck": "vision", "q": "¿Cuál es el problema central que resuelve su investigación?", "a": "El problema no es únicamente elegir un algoritmo. La Empresa gestiona el riesgo de forma predominantemente reactiva pese a disponer de muchos registros operativos. Nuestra pregunta fue cuánto riesgo operativo es realmente observable en los datos de geolocalización y bajo qué condiciones metodológicas puede medirse sin sobreestimarlo. El estudio por ello aborda dos frentes: capacidad de detección y validez del procedimiento de evaluación.", "level": "basico", "crit": false, "idea": "La tesis mide señal real y, al mismo tiempo, controla los mecanismos que podrían inflarla artificialmente."}, {"id": "g2", "deck": "vision", "q": "¿Cuál es el objetivo general?", "a": "Desarrollar un modelo predictivo para la detección de eventos de riesgo operativo en personal de una empresa de seguridad privada mediante análisis de datos de geolocalización. Los objetivos específicos operacionalizan ese propósito: validar variables, determinar qué puede construirse, reconstruir el pipeline, diseñar un protocolo de evaluación, comparar tres enfoques y caracterizar el techo de detectabilidad y el régimen temporal.", "level": "basico", "crit": false, "idea": "El objetivo general se ejecuta mediante seis objetivos específicos que van desde la medición hasta la evaluación."}, {"id": "g3", "deck": "vision", "q": "¿Cuál es la principal contribución de la tesis?", "a": "La contribución no es solo un modelo. Son tres componentes: un instrumento de 14 variables con validez de contenido, una línea base empírica de desempeño con la información realmente disponible y un protocolo de evaluación que controla cinco sesgos capaces de inflar el rendimiento. Además, el estudio demuestra que la principal restricción actual está en la infraestructura de datos, porque solo 3 variables fueron totalmente construibles y una parcialmente.", "level": "basico", "crit": false, "idea": "Instrumento + línea base + protocolo libre de sesgos; el cuello de botella es la observabilidad de los datos."}, {"id": "g4", "deck": "vision", "q": "¿Por qué sigue llamándose modelo predictivo si no demuestra anticipación de horas?", "a": "Predictivo se refiere a estimar la probabilidad o discriminación de un evento en observaciones no utilizadas para el entrenamiento. Nuestros resultados sí muestran señal discriminativa superior a una distribución nula, pero el análisis temporal no permite afirmar que esa señal aparezca con horas de anticipación. Por eso el título final habla de detección de eventos y no de detección temprana.", "level": "intermedio", "crit": false, "idea": "Capacidad predictiva de clasificación no equivale automáticamente a capacidad de anticipación temporal prolongada."}, {"id": "g5", "deck": "vision", "q": "¿Qué ocurrió con la hipótesis original?", "a": "El diseño original planteó multimodalidad, al menos 24 horas de anticipación y F1 superior a 0.80. La modalidad textual no pudo incorporarse, así que el componente multimodal no fue contrastado completamente. En geolocalización, ni el criterio de 24 horas ni el F1 objetivo se verificaron. De manera complementaria se evaluó si, pese a ello, existía señal superior al azar, y allí sí se encontró evidencia, especialmente para el ensamble de árboles.\n\nEvitar: Decir que demostraron que la multimodalidad no sirve: esa arquitectura completa no fue implementada.", "level": "intermedio", "crit": false, "idea": "No afirmamos que “el multimodal fracasó”; afirmamos que el planteamiento completo no pudo verificarse y que sus criterios de desempeño no se alcanzaron con la modalidad disponible."}, {"id": "g11", "deck": "vision", "q": "¿Por qué una empresa debería valorar una tesis que concluye que el modelo todavía no está listo para producción?", "a": "Porque evita desplegar una solución con una falsa sensación de eficacia y entrega un mapa concreto de inversión: qué vínculos crear, qué datos limpiar, qué etiquetas formalizar y cuánto rendimiento puede esperarse hoy. Saber que el modelo no está listo, con evidencia, es más valioso que desplegar uno que parece funcionar por fuga o comparaciones múltiples.", "level": "intermedio", "crit": false, "idea": "La tesis reduce riesgo de decisión tecnológica y prioriza inversiones de datos."}, {"id": "g6", "deck": "vision", "q": "¿Una tesis cuyo planteamiento inicial no se cumple puede considerarse exitosa?", "a": "Sí, porque una investigación no se evalúa por confirmar una expectativa, sino por producir evidencia válida. El estudio identificó por qué las métricas iniciales eran poco transferibles a un evento con prevalencia del orden de uno por mil, descubrió cinco fuentes de sesgo, cuantificó su impacto y estableció qué señal permanece después de corregirlas. Además, convirtió una limitación empresarial —la falta de integración— en un resultado empírico y accionable.\n\nEvitar: Presentar el no cumplimiento como “fracaso del proyecto”.", "level": "dificil", "crit": false, "idea": "El valor científico está en medir correctamente, no en obtener una métrica alta."}, {"id": "g7", "deck": "vision", "q": "¿Por qué el estudio terminó centrado en geolocalización si el diseño inicial era multimodal?", "a": "Porque la integración debe estar condicionada por la trazabilidad real de las fuentes. Durante la reconstrucción se comprobó que la modalidad textual y varios vínculos entre agente, turno, dispositivo y servicio no estaban disponibles con la calidad necesaria. Forzar una fusión habría introducido supuestos no verificables. Se tomó una decisión conservadora: modelar solo lo que podía operacionalizarse de forma reproducible y dejar la modalidad textual para una segunda etapa con revalidación completa.", "level": "dificil", "crit": false, "idea": "La reducción de alcance fue una decisión de validez, no una omisión arbitraria."}, {"id": "g8", "deck": "vision", "q": "¿Qué resultado cambiaría primero en La Empresa a partir de la tesis?", "a": "La prioridad no sería comprar un algoritmo más complejo. Sería establecer vínculos confiables agente-turno y dispositivo-servicio. El primero habilitaría seis de las diez variables hoy no operacionalizables; el segundo permitiría construir permanencia en zona asignada, una variable con consenso unánime de los expertos. Luego mejoraría la etiqueta de incidentes y ampliaría el histórico GPS.", "level": "dificil", "crit": false, "idea": "Primero mejorar la infraestructura de medición; después optimizar modelos."}, {"id": "g12", "deck": "vision", "q": "¿Cuál es el límite exacto de generalización de su trabajo?", "a": "Los resultados cuantitativos y el instrumento se validaron en una sola organización. Los 54 eventos no son una muestra aleatoria de los 2,447 eventos corporativos, sino el subconjunto con cobertura GPS confirmada. Por ello no generalizamos estadísticamente al sector. Lo transferible es principalmente el protocolo metodológico y la lógica de auditoría de datos; la magnitud de desempeño debe reestimarse en cada contexto.", "level": "dificil", "crit": false, "idea": "Transferimos método, no cifras de desempeño."}, {"id": "g9", "deck": "vision", "q": "Si solo pudiera defender una frase frente al jurado, ¿cuál sería?", "a": "Con la información hoy disponible existe señal asociada al riesgo, pero su magnitud y anticipación son mucho menores de lo que un protocolo sesgado puede hacer parecer; el principal techo está en la infraestructura de datos y no en la complejidad del algoritmo. Esa frase resume la pregunta, los resultados y la contribución metodológica.", "level": "extremo", "crit": false, "idea": "La tesis demuestra cuánto puede medirse de forma honesta y qué debe cambiar para medir más."}, {"id": "g10", "deck": "vision", "q": "¿Cuál es el hallazgo contraintuitivo más importante?", "a": "Que corregir el protocolo fue más determinante que cambiar de algoritmo. El ensamble de árboles llegó a mostrar recalls superiores al 70–80% durante etapas intermedias, pero después de corregir comparaciones múltiples el valor cayó a 48.15% en P95. Eso evidencia que una evaluación aparentemente excelente puede ser principalmente un artefacto.", "level": "extremo", "crit": false, "idea": "La evaluación puede dominar el resultado más que la arquitectura."}, {"id": "g63", "deck": "datos", "q": "¿Cuál fue el volumen real de datos procesados?", "a": "El conjunto de geolocalización contiene 61,273,298 observaciones. A partir de ellas se segmentaron 106,699 turnos y se identificaron 3,885,585 ventanas. La preparación final produjo 3,884,561 ventanas normales y 1,024 ventanas candidatas de evaluación, mientras que el número efectivo de eventos independientes fue 54.", "level": "basico", "crit": false, "idea": "Distinguir observaciones, turnos, ventanas y eventos; no mezclarlos."}, {"id": "c1.1", "deck": "datos", "q": "¿Cuántos datos usaron finalmente?", "a": "La base de geolocalización contiene 61,273,298 registros de 888 dispositivos, en un período de cinco meses y medio, del 15 de setiembre de 2025 al 23 de febrero de 2026. De ahí se construyeron 106,699 turnos y 3,884,561 ventanas de análisis. El recurso escaso no son los datos, son los eventos: 54 con cobertura de geolocalización confirmada.", "level": "intermedio", "crit": false}, {"id": "c1.2", "deck": "datos", "q": "¿Por qué solo 54 eventos si la empresa registra 2,447?", "a": "Por cobertura temporal. De los 2,447 eventos del registro corporativo, solo 301 caen dentro del rango de fechas que cubren los datos de geolocalización entregados. De esos 301, 54 tienen cobertura confirmada en el dispositivo asociado. La restricción no es la ocurrencia de eventos, es la ventana de datos disponible.", "level": "intermedio", "crit": false, "idea": "La pérdida ocurre por cobertura y vínculo, no por cherry-picking de resultados."}, {"id": "c1.4", "deck": "datos", "q": "¿Qué es una \"ventana\" y por qué de 30 minutos con paso de 15?", "a": "Una ventana es una secuencia de 30 observaciones consecutivas de un dispositivo, equivalente a 30 minutos al intervalo nominal de un minuto. El paso de 15 minutos genera solapamiento a la mitad, lo que aumenta la cantidad de ejemplos sin perder continuidad temporal. El diseño original exploró secuencias de 60 intervalos; la configuración implementada usa 30, y ambas están documentadas en el Anexo 5.", "level": "intermedio", "crit": false, "idea": "La ventana sirve para modelar; la evaluación corrige la dependencia inducida por solapamiento."}, {"id": "c1.5", "deck": "datos", "q": "El 10.52% de sus registros tiene coordenada cero. ¿Por qué no lo detectaron con el campo de GPS habilitado?", "a": "Porque ese campo no es confiable para eso. De las filas con coordenada (0,0), solo el 52.3% tiene el indicador de GPS en estado inactivo; el 47.7% lo reporta activo. Es decir, casi la mitad de las lecturas sin fijación satelital aparecen como si el GPS estuviera funcionando. Por eso filtramos directamente por el valor de la coordenada y no por el indicador de estado.", "level": "intermedio", "crit": false}, {"id": "c1.7", "deck": "datos", "q": "Tienen saltos de coordenada de 15,450 kilómetros. ¿Por qué no los eliminaron?", "a": "Decidimos no aplicar un umbral de exclusión, porque cualquier valor de corte habría sido arbitrario y habría eliminado observaciones potencialmente válidas. En su lugar atenuamos su influencia con una transformación logarítmica de la distancia. Antes de esa corrección, con normalización lineal, esos valores extremos dominaban la función de error y la curva de entrenamiento salía plana. Está declarado explícitamente en el Anexo 5: es una decisión de tratamiento, no una limpieza.", "level": "intermedio", "crit": false}, {"id": "c1.8", "deck": "datos", "q": "¿Cómo garantizan que la seudonimización preservó la integridad de los datos?", "a": "Con 41 chequeos automatizados sobre las tablas seudonimizadas y 30 sobre la exportación a formato columnar. Ambos conjuntos se superaron por completo en la corrida final. En corridas intermedias fallaron: 36 de 37 en el primer caso y 23 de 30 en el segundo, y cada fallo se rastreó y corrigió. En total documentamos trece defectos de procesamiento, entre ellos una inflación de cardinalidad que llevaba una tabla de 14.8 a 22.4 millones de filas, y la lectura de identificadores numéricos como decimales, que impedía por completo la correspondencia entre tablas.", "level": "intermedio", "crit": false}, {"id": "c1.10", "deck": "datos", "q": "¿Qué pasó con los dispositivos que estaban encendidos durante meses?", "a": "Los detectamos en la segmentación: la primera corrida produjo turnos de hasta 3,864 horas, equivalente a 161 días continuos, y el 44% de los dispositivos tenía cinco turnos o menos en todo el período. Son equipos de operación continua, asociados a vehículo o punto fijo, no a un agente individual. Los turnos que excedían 24 horas se resegmentaron en ventanas fijas de 12 horas, duración típica de la operación. El resultado final tiene mediana de 11.98 horas y máximo de 23.99.", "level": "intermedio", "crit": false}, {"id": "c1.11", "deck": "datos", "q": "Detectaron 723 turnos con una sola observación, y crecientes en el tiempo. ¿Eso no contamina su simulación de alertas?", "a": "Es una limitación que declaramos explícitamente y no pudimos cerrar. La progresión va de 21 a 148 casos mensuales entre setiembre y febrero, sin cambio proporcional en la cantidad de dispositivos activos, que se mantuvo entre 461 y 568. La hipótesis es degradación de cobertura hacia el final del período, que es justamente el tramo usado como evaluación operativa. La verificación pendiente es correlacionar la serie diaria de turnos con cobertura insuficiente contra la serie de incidentes detectados. Si hay relación, el volumen estimado de alertas está sesgado a la baja.\n\nNota para ustedes: si tienen tiempo antes de la defensa, corran esa verificación. Convierte una limitación abierta en un resultado.", "level": "intermedio", "crit": false}, {"id": "g64", "deck": "datos", "q": "¿Qué significa que el pipeline sea reproducible?", "a": "Que las transformaciones, cruces, reglas de seudonimización, segmentación, etiquetado y validaciones están implementadas de forma determinística/documentada y pueden ejecutarse nuevamente sobre las mismas fuentes para obtener resultados consistentes. Se validó con 41/41 chequeos de integridad y 30/30 de exportación, y se corrigieron 13 defectos durante la reconstrucción.", "level": "intermedio", "crit": false, "idea": "Reproducibilidad implica reglas y controles verificables, no solo tener scripts."}, {"id": "g68", "deck": "datos", "q": "¿Qué calidad tenía el GPS?", "a": "Había problemas relevantes: coordenadas centinela (0,0) en 10.52% de registros, saltos extremos en 0.03% con valores de hasta 15,450 km y degradación de cobertura hacia el tramo final, con 723 turnos de una sola observación. El campo de velocidad también se consideró no confiable. Estas condiciones se documentan y algunas se mitigan, pero no se ocultan.", "level": "intermedio", "crit": false, "idea": "La tesis no asume que “más de 61 millones” equivale a alta calidad."}, {"id": "c1.3", "deck": "datos", "q": "¿Por qué la ventana de datos empieza el 15 de setiembre de 2025 si la población arranca en 2023?", "a": "Los datos entregados corresponden a ese tramo. Durante el trabajo identificamos que existe un archivo histórico previo, con rango de enero de 2023 a setiembre de 2025, que no formó parte de la entrega. Es decir, hay aproximadamente dos años y medio adicionales de datos que existen y no se solicitaron en su momento. Lo declaramos como limitación del diseño de la investigación —no del dominio— y es la primera línea de trabajo futuro, porque multiplicaría el número de eventos utilizables.\n\nPor qué esta respuesta: es incómoda pero es la correcta. Decir \"es todo lo que existe\" sería falso y verificable. Reconocerlo convierte la limitación en una recomendación concreta.", "level": "dificil", "crit": true}, {"id": "c1.6", "deck": "datos", "q": "¿Por qué no usaron el campo de velocidad, que sería el indicador natural de inmovilidad?", "a": "Porque lo verificamos y no es confiable. Documentamos un caso donde el dispositivo reportó velocidad cero en el 95.2% de las observaciones del turno, mientras la variación de coordenadas mostraba un desplazamiento real de 1.36 kilómetros. Rediseñamos la variable de inmovilidad para calcularla por distancia geodésica entre observaciones consecutivas, con un criterio adicional de desplazamiento neto que distingue \"permaneció en el mismo lugar\" de \"avanzó despacio pero de forma constante\".", "level": "dificil", "crit": true, "idea": "Una variable disponible no es automáticamente una variable válida."}, {"id": "c1.9", "deck": "datos", "q": "¿Por qué la unidad de análisis es el dispositivo y no el agente?", "a": "Porque no existe vínculo confiable entre ambos. Encontramos tres esquemas de codificación de personal mutuamente inconsistentes en las fuentes: entre el registro maestro y la base de asignaciones hay 6 coincidencias sobre 211,424 y 4,362 registros, es decir 0.1%. Entre asignaciones y resguardos, 13 coincidencias. En contraste, entre el registro maestro y la base de movimientos hay 101,203 coincidencias sobre 147,139, un 68.8%, que sí constituye una familia coherente. Forzar un vínculo agente–turno con esos datos habría fabricado una relación inexistente. Este hallazgo determina el alcance de todo el estudio.", "level": "dificil", "crit": true, "idea": "Turno/dispositivo → ventana para modelar; evento para evaluar; experto para validar."}, {"id": "g65", "deck": "datos", "q": "¿Por qué la seudonimización es importante para la ciencia de datos, además de la privacidad?", "a": "Porque permite conservar consistencia relacional entre tablas sin exponer identificadores reales. Para un pipeline multimodal o multi-fuente, reemplazar de forma determinística los identificadores permite unir registros de la misma entidad de manera reproducible. Si se anonimizara de forma irreversible sin preservar correspondencias, algunos joins necesarios serían imposibles.", "level": "dificil", "crit": false, "idea": "Privacidad y preservación de integridad relacional deben coexistir."}, {"id": "g66", "deck": "datos", "q": "¿Cuál fue el hallazgo de “familias disjuntas” de código de personal?", "a": "La Empresa utiliza esquemas de codificación que no permiten un vínculo confiable y unívoco entre agente y turno/asignación. Esa desconexión bloquea variables como antigüedad, meses en puesto, rotación, cargo, supervisor y movimientos vehiculares. Es una de las razones por las que ocho variables no pudieron construirse.", "level": "dificil", "crit": false, "idea": "La falta de claves maestras es una limitación de medición, no un detalle administrativo."}, {"id": "g72", "deck": "datos", "q": "¿Por qué no usaron imágenes si existía una aplicación de imágenes?", "a": "Porque las tablas entregadas no contenían información de imagen o video. La existencia nominal de una aplicación no garantiza que sus datos estén disponibles en el extracto analítico. El estudio registra esa ausencia como hallazgo de disponibilidad efectiva, en vez de afirmar una modalidad que no pudo comprobarse.", "level": "dificil", "crit": false, "idea": "Catálogo de sistemas ≠ disponibilidad analítica real."}, {"id": "g74", "deck": "datos", "q": "¿Por qué conservaron coordenadas con saltos implausibles en lugar de limpiarlas totalmente?", "a": "Se evitó introducir un umbral físico arbitrario sin trazabilidad suficiente sobre reasignaciones o cambios de ubicación. Su efecto se comprimió mediante log1p y se documentó. Para una implementación futura sí sería recomendable construir reglas de calidad geoespacial con contexto de dispositivo, ubicación y servicio.", "level": "dificil", "crit": false, "idea": "Mitigación conservadora ahora; regla geoespacial contextual en futuro."}, {"id": "c1.12", "deck": "datos", "q": "¿Cómo verificaron que los 54 eventos corresponden al dispositivo correcto?", "a": "El cruce se hizo por número de línea telefónica: el número asociado al reporte de emergencia contra el número asociado al dispositivo en la base de rastreo. Construimos un mapa que contempla que un mismo dispositivo puede tener más de un número a lo largo del tiempo. Pero es una vinculación indirecta y lo declaramos como limitación: si una línea cambió de equipo durante el período, la atribución podría fallar. No tenemos forma de verificarlo con las fuentes disponibles, porque eso requeriría precisamente el vínculo agente–dispositivo que el estudio demuestra que no existe.", "level": "extremo", "crit": true}, {"id": "c1.13", "deck": "datos", "q": "¿Puede haber dispositivos compartidos entre varios agentes?", "a": "No podemos descartarlo, y es consecuencia directa del mismo hallazgo. Sin vínculo agente–dispositivo, no hay forma de saber si un equipo fue usado por distintas personas en distintos turnos. Está declarado como limitación porque afecta la validez de la unidad de análisis, no solo su representatividad.", "level": "extremo", "crit": false}, {"id": "g67", "deck": "datos", "q": "¿Por qué considera la infraestructura de datos un resultado científico y no solo un problema de TI?", "a": "Porque el objetivo del estudio incluye establecer qué variables validadas pueden operacionalizarse. La imposibilidad de construir variables relevantes modifica el espacio de hipótesis que un modelo puede aprender y establece un techo de detectabilidad. La tesis cuantifica esa distancia: 14 variables validadas, solo 3 completas y una parcial; de cuatro sólidas en pertinencia, solo una construible.", "level": "extremo", "crit": false, "idea": "La observabilidad del constructo depende de la arquitectura de datos."}, {"id": "g71", "deck": "datos", "q": "¿Puede haber sesgo de selección porque los 54 eventos con GPS no representen los 2,447?", "a": "Sí. La tesis lo declara explícitamente. La cobertura GPS puede estar correlacionada con puesto, cliente o zona; por tanto, no afirmamos intercambiabilidad. Los resultados describen el subconjunto observable. La solución futura es ampliar histórico y mejorar trazabilidad para evaluar más eventos y comparar su distribución con el universo corporativo.", "level": "extremo", "crit": false, "idea": "Reconocer selection bias y limitar inferencia."}, {"id": "g73", "deck": "datos", "q": "¿Qué controles de calidad impiden que un join multiplique filas y genere señal artificial?", "a": "El pipeline incorporó validaciones de integridad y cardinalidad; durante la reconstrucción se detectaron defectos de procesamiento y se corrigieron antes de la exportación final. La tesis reporta 41 chequeos de integridad y 30 de exportación conformes. La idea de fondo es validar conteos y cardinalidades después de cada integración, no confiar en una clave declarada sin verificar su unicidad.", "level": "extremo", "crit": false, "idea": "Cada join debe auditar cardinalidad y conservación de registros."}, {"id": "g75", "deck": "datos", "q": "Si mañana La Empresa corrige solo un problema de datos, ¿cuál maximiza el valor?", "a": "El vínculo agente-turno, porque habilitaría seis de las diez variables no operacionalizables. El segundo sería dispositivo-servicio, necesario para permanencia en zona asignada, una variable con consenso unánime. Después ampliaría el histórico GPS y enriquecería la etiqueta de incidentes.", "level": "extremo", "crit": false, "idea": "Priorizar claves maestras antes que más algoritmos."}, {"id": "g13", "deck": "metodo", "q": "¿Por qué utilizaron un enfoque mixto?", "a": "Porque el problema requería dos tipos de evidencia. La parte cuantitativa permitió procesar registros, construir variables y evaluar modelos. La parte cualitativa permitió validar la pertinencia y claridad de las variables y explicar artefactos que los datos por sí solos no podían revelar, como el subregistro de riesgos comunicados por radio o la interpretación de patrones de antigüedad. La triangulación evitó conclusiones puramente algorítmicas desconectadas del dominio.", "level": "basico", "crit": false, "idea": "El componente cualitativo no adorna al cuantitativo: corrige y contextualiza su interpretación."}, {"id": "g14", "deck": "metodo", "q": "¿Por qué el diseño es no experimental?", "a": "Porque no manipulamos deliberadamente la exposición, el comportamiento del personal ni la ocurrencia de incidentes. Analizamos registros generados en el entorno operativo real. Las variables se observaron tal como existían en los sistemas de La Empresa, y los modelos se entrenaron sobre datos históricos.", "level": "basico", "crit": false, "idea": "Observación de datos reales sin intervención causal."}, {"id": "c4.1", "deck": "metodo", "q": "¿Por qué siete expertos y no más?", "a": "Siete corresponde a la práctica habitual en validación de contenido por juicio de expertos y permite aplicar el coeficiente V de Aiken con intervalos de confianza. Declaramos como limitación que un panel de ese tamaño produce intervalos amplios, y que todos los jueces provienen de la misma organización y contexto nacional, por lo que el instrumento constituye una propuesta validada en un contexto específico y no un estándar sectorial.", "level": "intermedio", "crit": false, "idea": "El tamaño del panel se compensa parcialmente explicitando incertidumbre, no ocultándola."}, {"id": "c4.4", "deck": "metodo", "q": "En pertinencia, once variables superan el azar pero solo cuatro alcanzan el umbral sustantivo. ¿Eso no debilita el instrumento?", "a": "Refleja con precisión el estado de la evidencia con siete jueces. Cuatro variables tienen respaldo sólido en pertinencia; siete más superan el azar sin alcanzar el umbral exigente. En claridad el resultado es mejor: las catorce superan el azar y nueve alcanzan el umbral sustantivo, lo que indica que las definiciones operativas fueron comprendidas de manera consistente. Reportar los cuatro y los nueve, en lugar de solo los valores puntuales, es más honesto que presentar el instrumento como uniformemente validado.", "level": "intermedio", "crit": false}, {"id": "c4.7", "deck": "metodo", "q": "¿Qué aportó realmente el componente cualitativo, más allá de validar variables?", "a": "Tres hallazgos que cambiaron el análisis cuantitativo. Primero, la existencia de un código encubierto de comunicación por radio para señalar riesgo sin activar el mecanismo formal, lo que implica que nuestra etiqueta subestima la ocurrencia real del fenómeno. Segundo, la atribución del patrón preliminar de mayor incidencia en agentes de menor antigüedad al estilo de reporte y a la asignación de puesto, no a un riesgo real diferenciado; sin ese contraste habríamos concluido algo incorrecto. Tercero, la explicación de la asimetría en el registro de novedades como artefacto de que ciertos puestos documentan en aplicaciones distintas. Los tres están en la sección de triangulación.", "level": "intermedio", "crit": false}, {"id": "g15", "deck": "metodo", "q": "¿Por qué describen el estudio como transversal si trabajan con series temporales?", "a": "La temporalidad de los registros no convierte automáticamente el diseño en longitudinal. El estudio analiza un período delimitado de información ya generada y no realiza seguimiento prospectivo de una cohorte para observar cambios causales en el tiempo. Aun así, reconocemos que existe estructura temporal dentro de los datos y por eso se preserva en ventanas, turnos y en la simulación temporal de los últimos 30 días.", "level": "intermedio", "crit": false, "idea": "Diseño de investigación y estructura temporal del dato son conceptos distintos."}, {"id": "g17", "deck": "metodo", "q": "¿Por qué el muestreo es no probabilístico e intencional?", "a": "Porque los datos provienen de una organización específica y se seleccionan según disponibilidad, trazabilidad y criterios de calidad. Los expertos también requieren experiencia específica de dominio. No pretendemos inferencia poblacional probabilística al sector; por eso la limitación de generalización está declarada explícitamente.", "level": "intermedio", "crit": false, "idea": "La selección responde a disponibilidad y pertinencia, no a representatividad probabilística."}, {"id": "c4.2", "deck": "metodo", "q": "¿Cómo calcularon los intervalos de confianza del coeficiente V?", "a": "Con el método score de Penfield y Giacobbi (2004), sobre una escala de tres niveles, donde el número de categorías menos uno es dos y el número de jueces es el de valoraciones válidas por variable. Aplicamos dos criterios de decisión: superación del valor de azar, que en una escala de tres niveles es 0.50, evaluada sobre el límite inferior del intervalo al 90%; y umbral sustantivo de 0.70 sobre el límite inferior del intervalo al 95%. Las matrices crudas de valoraciones están en el Anexo 4, de modo que el cálculo es replicable.", "level": "dificil", "crit": true}, {"id": "g18", "deck": "metodo", "q": "¿Por qué usan todos los 54 eventos pero solo 100,000 ventanas normales en modelos supervisados?", "a": "Los eventos son escasos y por eso se incorporan todos. Las ventanas normales son millones; usar todas obligaría a reentrenar sobre un volumen muy grande en cada fold sin aportar proporcionalmente más información sobre el comportamiento normal. Se seleccionaron 100,000 normales con semilla fija para reproducibilidad. El autoencoder, en cambio, sí fue entrenado con las 3,884,561 ventanas normales.", "level": "dificil", "crit": false, "idea": "No se submuestrea la clase rara; se controla el volumen redundante de la clase normal."}, {"id": "g19", "deck": "metodo", "q": "¿Por qué no imputaron turnos con menos de 15 observaciones?", "a": "Porque el mínimo de observaciones es necesario para calcular variables derivadas con sentido. Imputar secuencias extremadamente incompletas habría creado señal sintética en un problema donde ya existe gran incertidumbre y escasez de eventos. La decisión fue conservadora: excluir en lugar de inventar trayectoria.", "level": "dificil", "crit": false, "idea": "En datos GPS críticos, imputar demasiado puede fabricar patrones inexistentes."}, {"id": "c4.3", "deck": "metodo", "q": "¿Por qué 0.50 como valor de azar y no 0.70, que es el umbral convencional?", "a": "Porque son dos cosas distintas y el documento las separa deliberadamente. Con una escala de tres niveles, el coeficiente V se calcula como la media menos uno, dividido entre dos. Bajo respuesta aleatoria la media esperada es dos, lo que da un V de 0.50. Ese es el valor de azar en sentido estricto. El 0.70 es un mínimo convencional de aceptabilidad, no un nivel de azar, y lo usamos como umbral sustantivo. Mantener las dos preguntas separadas —¿supera el azar? y ¿alcanza aceptabilidad?— es lo que justifica el diseño de dos niveles de confianza.", "level": "extremo", "crit": true}, {"id": "c4.5", "deck": "metodo", "q": "Su escala de tres niveles incluye una opción intermedia. ¿No sesga las respuestas?", "a": "Es una limitación que declaramos. Parte de la literatura del área opta por escalas de número par de opciones precisamente para eliminar la posición intermedia y forzar una toma de posición. Con nuestra escala, una valoración \"media\" contribuye con 0.50 al coeficiente, exactamente el valor de azar, lo que puede diluir el resultado. Si repitiéramos el estudio, usaríamos cuatro niveles.", "level": "extremo", "crit": false}, {"id": "c4.6", "deck": "metodo", "q": "¿Todas las celdas de su matriz están completas?", "a": "No. Algunas valoraciones no quedaron registradas de forma íntegra durante las entrevistas, principalmente porque el entrevistador encadenó preguntas de pertinencia y claridad sin pausa. Recuperamos de las grabaciones las que efectivamente se emitieron y las incorporamos; las que no fueron emitidas se tratan como no aplicables y se excluyen del cálculo, sin contarlas como desfavorables. El número de valoraciones válidas por variable está consignado en la matriz del Anexo 4, y en algunas variables es de cuatro a seis en lugar de siete, lo que amplía los intervalos correspondientes.", "level": "extremo", "crit": true}, {"id": "g21", "deck": "metodo", "q": "¿El uso de ventanas solapadas viola independencia estadística?", "a": "Sí, las ventanas solapadas no son independientes entre sí. Precisamente por eso la tesis no calcula el desempeño final como si cada ventana fuera una unidad independiente. La unidad de evaluación se reduce a una ventana representativa por evento y se excluyen dispositivos del entrenamiento. Las ventanas solapadas se aceptan como mecanismo de representación temporal, no como réplicas independientes para inferencia.", "level": "extremo", "crit": false, "idea": "Reconocemos dependencia y evitamos convertirla en pseudorreplicación."}, {"id": "g22", "deck": "metodo", "q": "¿Cómo justifican que la etiqueta “emergencia” represente riesgo operativo?", "a": "La etiqueta es una aproximación observable, no una representación perfecta del constructo. La tesis diferencia explícitamente riesgo operativo de activación formal de emergencia y reconoce subregistro por situaciones comunicadas mediante códigos de radio. El juicio experto valida el constructo y también revela esa limitación. Por eso hablamos de validez de constructo limitada y recomendamos formalizar categorías más ricas.", "level": "extremo", "crit": false, "idea": "La etiqueta es proxy imperfecto; no confundimos el registro con el fenómeno completo."}, {"id": "g23", "deck": "metodo", "q": "¿No hay circularidad al usar expertos para definir variables y luego usar entrevistas para interpretar resultados?", "a": "No, porque cumplen funciones distintas. Primero se utiliza juicio estructurado para evaluar pertinencia y claridad de variables. Después los hallazgos cualitativos abiertos se usan para contextualizar patrones y problemas de registro. No se usa la interpretación cualitativa para fabricar resultados cuantitativos; se triangulan fuentes independientes con objetivos diferentes.", "level": "extremo", "crit": false, "idea": "Validación de contenido y triangulación interpretativa son etapas distintas."}, {"id": "g25", "deck": "metodo", "q": "¿Qué error metodológico habría sido más grave: tener pocos eventos o evaluar mal los pocos eventos?", "a": "Evaluar mal. Un tamaño pequeño amplía incertidumbre, pero un protocolo sesgado puede producir resultados sistemáticamente falsos. La tesis muestra que comparaciones múltiples podían generar una probabilidad de cruce por azar de 77.4%, muy cercana al recall aparente de 81.48%. Con pocos eventos, el control de sesgos es aún más importante.", "level": "extremo", "crit": false, "idea": "La incertidumbre se puede declarar; el sesgo no corregido invalida la conclusión."}, {"id": "c2.1", "deck": "modelos", "q": "¿Por qué eligieron un autoencoder LSTM?", "a": "Porque el problema tiene dos características que lo sugieren: los datos son secuencias temporales, y los eventos son extremadamente raros. Un autoencoder aprende a reconstruir el comportamiento normal y señala como anómalo lo que no logra reconstruir, sin necesitar ejemplos etiquetados de la clase rara. La componente recurrente captura dependencias temporales que un modelo de instantáneas no vería.", "level": "intermedio", "crit": false, "idea": "La elección inicial era razonable para escasez de etiquetas; el resultado empírico mostró su límite."}, {"id": "c2.3", "deck": "modelos", "q": "¿Por qué agregaron un ensamble de árboles si su hipótesis era sobre arquitecturas recurrentes?", "a": "Como diagnóstico. Necesitábamos distinguir si el techo del autoencoder venía del enfoque o de los datos. Un modelo de familia distinta, que sí observa las etiquetas, responde esa pregunta. El resultado —recall sustancialmente mayor— confirmó que la señal recuperable en los datos supera lo que el enfoque no supervisado extrae. Es un ejercicio de diagnóstico, no un cambio de hipótesis, y así está encuadrado en la discusión.", "level": "intermedio", "crit": false}, {"id": "c2.6", "deck": "modelos", "q": "¿Qué es la confusión de identidad de dispositivo y por qué importa?", "a": "Es una forma de fuga de datos descrita en la literatura. Si el modelo observa durante el entrenamiento el comportamiento habitual del mismo dispositivo cuyo evento se evalúa, puede memorizar la firma de ese dispositivo en lugar de aprender el patrón de riesgo. La corrección es excluir del entrenamiento todas las ventanas de los dispositivos cuyos eventos están retenidos en esa partición. Lo verificamos además con un escenario sintético sin señal real: antes de la corrección producía 35% de recall cuando debía dar alrededor del 5%.", "level": "intermedio", "crit": false}, {"id": "c2.7", "deck": "modelos", "q": "¿Por qué usaron validación cruzada por evento y no una partición 70/30?", "a": "Con 54 positivos, un solo corte del 30% deja unos 16 eventos de prueba y una única medición, muy inestable. La validación cruzada por evento en ocho particiones hace que cada uno de los 54 eventos sea, en alguna ronda, un caso de prueba sobre un modelo que nunca lo vio, y promedia ocho mediciones. Es más exigente, no menos.", "level": "intermedio", "crit": false}, {"id": "c2.11", "deck": "modelos", "q": "¿Por qué el ensamble de árboles gana al modelo recurrente, si su hipótesis apostaba al segundo?", "a": "Por dos razones que se refuerzan. Primero, con 54 eventos un modelo de menor capacidad y mayor sesgo inductivo tiene ventaja sobre una arquitectura profunda; es un resultado documentado en la literatura para tamaños muestrales limitados. Segundo, y más específico: los ensambles de árboles incorporan promediado sobre múltiples estimadores por construcción, es decir, operan con la varianza ya controlada. El modelo recurrente necesitó diez inicializaciones para alcanzar un régimen comparable. La diferencia en configuración de semilla única no era de capacidad de aprendizaje, era de estabilidad de la estimación.", "level": "intermedio", "crit": false}, {"id": "c2.13", "deck": "modelos", "q": "¿Por qué reportan recall e intervalos en lugar de F1-Score, como planteaba la hipótesis original?", "a": "Porque el criterio original no tenía sustento teórico para este dominio. Los umbrales que consideramos inicialmente provenían de estudios sobre conjuntos públicos de referencia con prevalencia balanceada y etiquetado exhaustivo. Con una prevalencia de 54 eventos entre casi cuatro millones de ventanas, el estándar apropiado es recall por umbral con intervalos de confianza, contrastado contra la prevalencia base y contra una distribución nula de etiquetas aleatorias. El criterio inicial se conserva en el documento como referencia del diseño original y su grado de cumplimiento se determina empíricamente.", "level": "intermedio", "crit": false}, {"id": "c2.16", "deck": "modelos", "q": "¿Por qué eliminaron la curva ROC y la matriz de confusión del criterio de evaluación?", "a": "Se conservan como material diagnóstico del enfoque no supervisado, con nota explícita, pero no son criterio de decisión. La razón es que ambas son métricas por ventana, y la unidad de interés es el evento: a un jurado no le importa cuántas ventanas se clasificaron bien, sino cuántos incidentes se detectaron. Con una prevalencia de este orden, las métricas por ventana son dominadas por la clase mayoritaria y transmiten una impresión engañosa.", "level": "intermedio", "crit": false}, {"id": "c3.2", "deck": "modelos", "q": "¿Entonces el modelo no sirve para prevenir?", "a": "No en el sentido de anticipar con horas de margen. Sí en un sentido más limitado y verificable: la proporción de eventos detectados con retraso es nula, lo que indica ausencia de rezago sistemático. Un detector que señala en tiempo casi real, con un volumen de aproximadamente 17 alertas diarias para toda la flota, tiene valor para reducir el tiempo de respuesta, no para evitar la ocurrencia. Y hay un valor potencial adicional que no pudimos medir: los casos en que el agente no activa el mecanismo formal de emergencia.", "level": "intermedio", "crit": false}, {"id": "c3.3", "deck": "modelos", "q": "Reportan una mediana de anticipación de 33.4 minutos. ¿Sobre cuántos casos?", "a": "Sobre tres. Es una muestra demasiado pequeña para sostener cualquier afirmación general, y lo decimos explícitamente. La cifra se reporta por completitud, no como resultado.", "level": "intermedio", "crit": false}, {"id": "g44", "deck": "modelos", "q": "¿Cómo estaba configurado el autoencoder final?", "a": "La línea base experimental usó un codificador recurrente con espacio latente de 16 unidades, un decodificador equivalente, capa lineal de salida, secuencias de 30 observaciones y batch de 256. El diseño multimodal original era mayor, con dos capas de 64 y 32 unidades, pero no fue la arquitectura final implementada con geolocalización.", "level": "intermedio", "crit": false, "idea": "Distinguir arquitectura originalmente propuesta de línea base realmente ejecutada."}, {"id": "g47", "deck": "modelos", "q": "¿Por qué implementaron después un clasificador recurrente supervisado?", "a": "Para probar si la señal existía pero no podía capturarse mediante reconstrucción no supervisada. Mantiene una inductiva temporal similar a LSTM, pero aprende directamente de las etiquetas. Eso permitió evaluar si el problema era el objetivo de entrenamiento más que la temporalidad de la arquitectura.", "level": "intermedio", "crit": false, "idea": "Es una extensión controlada de la familia recurrente para aprovechar supervisión."}, {"id": "c2.2", "deck": "modelos", "q": "El autoencoder alcanza AUC de 0.60 y recall entre 5 y 12%. ¿No es un fracaso?", "a": "Es un resultado modesto y lo reportamos como tal. Pero la interpretación importa: probamos cuatro configuraciones distintas —más épocas, más variables de contexto temporal, normalización por dispositivo— y las cuatro convergieron al mismo techo. La razón entre la mediana del error de reconstrucción de ventanas con evento y sin evento se mantuvo estable en torno a 1.38. Eso descarta que el problema fuera falta de entrenamiento o de variables: el techo es del enfoque no supervisado aplicado a este problema. Y ese descarte es lo que justificó pasar a modelos supervisados, que efectivamente triplicaron el desempeño.", "level": "dificil", "crit": true}, {"id": "c2.4", "deck": "modelos", "q": "Su primer resultado fue 72%, después 81%, y el final 48%. ¿Cómo sabemos que el 48% es el correcto?", "a": "Esa secuencia es el hallazgo metodológico central del trabajo, no un accidente. El 72% inicial nos resultó sospechosamente alto y motivó una revisión que encontró confusión de identidad de dispositivo: el modelo veía comportamiento normal del mismo dispositivo cuyo evento estaba evaluando. Al corregirlo con exclusión por dispositivo y normalización, el resultado subió a 81%, lo que disparó una sospecha mayor. La segunda revisión encontró el problema de comparaciones múltiples. Solo después de corregir los tres el resultado bajó a 48.15%.\n\nQue sea el correcto se sostiene en tres verificaciones independientes: una prueba de etiquetas aleatorias de 30 repeticiones cuya distribución nula tiene media 4.63% y máximo 11.11%, muy por debajo del valor observado; una repetición con semilla distinta de partición que dio 46.30%; y un algoritmo alternativo, potenciación de gradiente, que dio 55.56%. Los tres son consistentes.", "level": "dificil", "crit": true}, {"id": "c2.8", "deck": "modelos", "q": "¿Usaron todos los datos o una muestra?", "a": "Depende del modelo, y está declarado. El autoencoder se entrenó sobre la totalidad de las 3,884,561 ventanas normales. Los modelos supervisados y las simulaciones operativas se entrenaron sobre una muestra aleatoria de 100,000 ventanas normales, con semilla fija para reproducibilidad. La razón es que la validación cruzada por evento exige reentrenar el modelo en cada partición, y 100,000 ventanas es un tamaño más que suficiente para caracterizar el comportamiento normal de referencia. En todos los casos los 54 eventos se usaron completos, sin muestreo.", "level": "dificil", "crit": true}, {"id": "c2.10", "deck": "modelos", "q": "El ensamble de diez inicializaciones sube el recall de 5.6% a 31.5%. ¿No es sospechoso que un cambio tan simple mejore tanto?", "a": "Es el hallazgo metodológico más interesante del trabajo, y tiene explicación. En condiciones de escasez extrema de etiquetas, el resultado de una red profunda depende fuertemente de la inicialización aleatoria de sus parámetros. Promediar las probabilidades de diez modelos con distinta inicialización reduce esa varianza. Lo revelador es que la mejora crece con la exigencia del umbral: 9.3 puntos en el percentil 90 y 25.9 puntos en el percentil 99.9. Es decir, la varianza de inicialización afecta sobre todo la cola extrema de la distribución de puntajes, que es precisamente donde opera la detección de eventos raros. La lectura de fondo es que reportar el resultado de una sola inicialización, en este régimen, no constituye una estimación confiable del desempeño.", "level": "dificil", "crit": true}, {"id": "c2.12", "deck": "modelos", "q": "¿Cuál de los dos modelos recomiendan?", "a": "En el umbral operativamente relevante, el percentil 99.9, no hay base estadística para preferir uno. El recall es 31.5% para el recurrente y 38.9% para el ensamble de árboles, con intervalos de confianza que se superponen ampliamente —de 20.4 a 44.4% y de 25.9 a 51.9%— y un volumen de alertas prácticamente idéntico, 16.9 frente a 15.9 incidentes diarios. Somos explícitos en el documento en que la superposición de intervalos no constituye prueba formal de equivalencia; lo que decimos es que no hay evidencia concluyente de diferencia. En umbrales intermedios el ensamble de árboles sí mantiene ventaja en ambos ejes.", "level": "dificil", "crit": true}, {"id": "c3.1", "deck": "modelos", "q": "El título habla de detección y su hipótesis original hablaba de 24 horas de anticipación. ¿Qué pasó?", "a": "La hipótesis original no se verificó en ese componente y lo reportamos abiertamente. De los 54 eventos, 51 —el 94.4%— quedan detectados dentro de una banda de quince minutos respecto del instante del incidente. Solo 3 muestran más de quince minutos de anticipación. Ningún evento aparece con retraso superior a quince minutos. Es decir, el sistema opera en un régimen casi simultáneo al evento, no de anticipación con horas de margen. Por eso el título dice \"detección de eventos\" y no \"detección temprana\": ajustamos la formulación a lo que la evidencia sostiene.", "level": "dificil", "crit": true}, {"id": "g45", "deck": "modelos", "q": "¿Por qué el autoencoder falló relativamente frente a modelos supervisados?", "a": "Porque una anomalía de reconstrucción no necesariamente coincide con el evento de riesgo. Un autoencoder aprende lo frecuente, pero puede reconstruir bien patrones asociados a riesgo si éstos no son visualmente/temporalmente raros, y puede marcar como anómalas variaciones benignas. Con etiquetas, los modelos supervisados pueden aprender directamente la señal discriminativa relevante, aunque con gran incertidumbre por los 54 eventos.", "level": "dificil", "crit": false, "idea": "“Raro” en el espacio de datos no es lo mismo que “riesgoso” en el dominio."}, {"id": "g46", "deck": "modelos", "q": "¿Qué evidencia muestra que no era solo problema de entrenamiento insuficiente del autoencoder?", "a": "Se probaron cuatro configuraciones: 10 y 50 épocas, 3 y 7 variables, y normalización por dispositivo. El recall quedó aproximadamente entre 6.65% y 8.33% bajo el protocolo anterior, con AUC descriptivo entre 0.567 y 0.610; además, la razón de medianas de error se mantuvo alrededor de 1.38. Las pérdidas convergían sin divergencia clara. Esto sugiere una limitación de discriminación más que solo falta de épocas.", "level": "dificil", "crit": false, "idea": "Variar entrenamiento y variables no separó sustancialmente las distribuciones."}, {"id": "g48", "deck": "modelos", "q": "¿Cómo resolvieron el desbalance durante entrenamiento del recurrente?", "a": "Con aproximadamente un evento por cada dos mil ventanas normales, el muestreo aleatorio simple producía lotes sin positivos. Se empleó muestreo ponderado para asegurar una composición equilibrada por lote, evitando una ponderación extrema en la función de pérdida que podía introducir inestabilidad. La evaluación, en cambio, conserva la distribución real.", "level": "dificil", "crit": false, "idea": "Balancear lotes para aprender; no balancear la evaluación."}, {"id": "g49", "deck": "modelos", "q": "¿Por qué un ensamble de árboles puede competir o superar a una LSTM en un problema temporal?", "a": "Porque el número de eventos positivos es muy pequeño y las variables utilizadas ya contienen resúmenes temporales derivados. En ese régimen, un modelo de menor capacidad puede generalizar mejor y ser menos sensible a inicialización. La tesis no asume que “deep learning siempre gana”; de hecho, los árboles muestran ventaja descriptiva en varios umbrales.", "level": "dificil", "crit": false, "idea": "Complejidad de modelo debe ajustarse a cantidad de señal y tamaño efectivo de muestra."}, {"id": "g52", "deck": "modelos", "q": "¿Por qué normalizar por dispositivo?", "a": "Los dispositivos presentan escalas sistemáticamente distintas. En un escenario sintético sin señal real, esa heterogeneidad produjo 35% de recall frente a 5% esperable, mostrando que el modelo podía reconocer escala del dispositivo en lugar de riesgo. Normalizar por dispositivo reduce esa señal espuria.", "level": "dificil", "crit": false, "idea": "La normalización es un control contra fingerprinting del dispositivo."}, {"id": "g54", "deck": "modelos", "q": "¿Por qué aplicaron log1p a la distancia?", "a": "Porque 0.03% de observaciones contenía saltos implausibles de hasta 15,450 km. Bajo normalización lineal, esos extremos dominaban el error cuadrático y aplanaban el entrenamiento. log1p comprime la cola manteniendo orden y diferencias relativas, reduciendo la influencia de esos artefactos sin fijar un umbral arbitrario de exclusión.", "level": "dificil", "crit": false, "idea": "Transformación robusta para cola extrema, no borrado selectivo de datos."}, {"id": "g56", "deck": "modelos", "q": "¿Por qué promediar diez inicializaciones mejora tanto el recurrente?", "a": "Con solo 54 eventos, la frontera aprendida es muy sensible a la semilla. Una sola inicialización dio 5.6% de recall en P99.9; el promedio de diez modelos elevó ese valor a 31.5%, y cinco semillas dieron un resultado intermedio de 24.1%. El ensamble reduce varianza de parámetros y estabiliza especialmente la cola extrema donde opera P99.9.", "level": "dificil", "crit": false, "idea": "El ensamble corrige inestabilidad, no añade nueva información."}, {"id": "g58", "deck": "modelos", "q": "¿Por qué no usar Transformers para la serie GPS?", "a": "No era necesario para responder la pregunta central y hubiera aumentado capacidad y riesgo de sobreajuste con 54 eventos. La arquitectura recurrente es adecuada para secuencias cortas y permitía comparar de forma controlada el enfoque no supervisado y supervisado. Un Transformer temporal podría evaluarse cuando aumente el número de eventos y la riqueza de variables.", "level": "dificil", "crit": false, "idea": "Primero establecer señal y protocolo; después aumentar capacidad."}, {"id": "g61", "deck": "modelos", "q": "¿Por qué una única ventana por evento y cuál eligieron?", "a": "Para evitar comparaciones múltiples, la evaluación final toma una única ventana por evento, la más próxima al instante del incidente. Antes, evaluar ~29 ventanas por evento daba múltiples oportunidades de cruzar el umbral por azar y generaba 77.4% de probabilidad de al menos un cruce en P95.", "level": "dificil", "crit": false, "idea": "La elección reduce pseudorreplicación y oportunidades de acierto accidental."}, {"id": "c2.5", "deck": "modelos", "q": "Explíqueme el sesgo de comparaciones múltiples en sus propios términos.", "a": "Cada evento tenía aproximadamente 29 ventanas dentro de la banda de exclusión, y las evaluábamos todas como intentos independientes de detección. Con una tasa de falsa alarma del 5% por ventana, la probabilidad de que al menos una supere el umbral por azar es 1 menos 0.95 elevado a 29, equivalente al 77.4%. El recall que observábamos antes de corregir era 81.48%. La coincidencia entre ambas cifras indica que prácticamente todo el desempeño aparente era artefacto del diseño de evaluación, no señal. La corrección fue evaluar una sola ventana por evento, la más próxima al instante del incidente, lo que redujo el conjunto de evaluación de 1,589 a 54 ventanas.", "level": "extremo", "crit": true}, {"id": "c2.9", "deck": "modelos", "q": "¿Por qué 100,000 y no otro número? ¿Hicieron un cálculo de tamaño de muestra?", "a": "No. Fue una decisión práctica: un tamaño manejable para ocho reentrenamientos y claramente suficiente para el propósito. No derivamos ese valor de un cálculo formal de potencia. Lo que sí podemos afirmar es que la escasez que limita el estudio está en los positivos, no en los negativos: con 54 eventos, agregar ventanas normales no reduce la amplitud de los intervalos de confianza. Una comparación entre 100,000, 500,000 y el total sería una verificación razonable y no la hicimos.", "level": "extremo", "crit": false}, {"id": "c2.14", "deck": "modelos", "q": "¿Por qué la prueba de etiquetas aleatorias tiene 30 repeticiones para un modelo y 10 para el otro?", "a": "Por costo computacional: cada repetición del modelo recurrente implica reentrenar la red completa en las ocho particiones. Y tiene una consecuencia que declaramos: con 10 repeticiones el valor de probabilidad empírico mínimo alcanzable es aproximadamente 0.091, de modo que no podemos sostener significación al cinco por ciento para el clasificador recurrente. La afirmación con respaldo estadístico se apoya en las 30 repeticiones del ensamble de árboles, con un valor de 0.032. Para el modelo recurrente la evidencia es indicativa, y así está redactado.", "level": "extremo", "crit": false}, {"id": "c2.15", "deck": "modelos", "q": "Su tasa de falsas alarmas en la tabla de recall es el propio percentil. ¿No es circular?", "a": "Sí, en parte, y por eso no es la medición que reportamos como evidencia operativa. Fijar el umbral en el percentil 99 implica por definición que el 1% de las ventanas normales de entrenamiento lo superan. La medición independiente es la simulación de volumen de alertas: entrenamos solo con datos anteriores a los últimos 30 días y evaluamos sobre ese tramo no observado. De ahí sale la cifra de aproximadamente 17 incidentes diarios, que es la que sostiene la viabilidad operativa.", "level": "extremo", "crit": false}, {"id": "c2.17", "deck": "modelos", "q": "¿Cuántas épocas entrenó efectivamente cada configuración?", "a": "No lo tenemos registrado, y está declarado así en el Anexo 5. El máximo configurado fue de 50 épocas, con detención temprana de paciencia 4 y mejora mínima del 0.1%. El número efectivo de cada corrida quedó en la salida de consola y no se persistió. Es una omisión de trazabilidad que reconocemos; lo que sí está documentado es el criterio de parada, que es la información con valor metodológico.", "level": "extremo", "crit": false}, {"id": "c3.4", "deck": "modelos", "q": "En su capítulo mencionan que un cálculo anterior de este análisis tenía una inconsistencia. Explíquela.", "a": "El script clasificaba los eventos en tres categorías usando un umbral de quince minutos para \"anticipado\", pero calculaba la mediana de anticipación sobre todos los eventos con diferencia negativa, sin aplicar ese umbral. Eran dos poblaciones distintas reportadas juntas sin declarar el cambio de criterio: 3 eventos en un caso, 21 en el otro. La detectó nuestro asesor al revisar la coherencia entre ambas cifras. Unificamos el umbral en todo el procedimiento y auditamos los demás scripts de métricas para verificar que el patrón no se repitiera. No encontramos otro caso. Lo documentamos en el capítulo porque forma parte del proceso de control de calidad del trabajo.", "level": "extremo", "crit": true}, {"id": "c3.5", "deck": "modelos", "q": "¿El análisis de régimen temporal significa que detectaron los 54 eventos?", "a": "No, y es una distinción importante que el documento explicita. Ese análisis describe la posición temporal de la ventana más próxima a cada evento; no implica que los 54 hayan sido detectados a un umbral fijo. Las cifras de detección son las de las tablas de recall, y en el percentil 99.9 corresponden a 31.5% y 38.9% según el modelo. Son dos análisis relacionados pero distintos.", "level": "extremo", "crit": false}, {"id": "g50", "deck": "modelos", "q": "¿Por qué no usar XGBoost directamente en lugar de Random Forest/ensamble?", "a": "El objetivo era tener una familia de comparación no recurrente y menos compleja frente a la arquitectura profunda, no agotar todas las técnicas. Como verificación de consistencia sí se evaluó una variante de potenciación de gradiente, que alcanzó recall 55.56% con IC 42.59–68.52%, consistente con el orden de magnitud del modelo de referencia. Eso sugiere que el hallazgo no depende de un único algoritmo de árboles.", "level": "extremo", "crit": false, "idea": "Se usa baseline robusta y una variante de boosting como chequeo, no como búsqueda exhaustiva de SOTA."}, {"id": "g51", "deck": "modelos", "q": "¿Cómo sabe que el modelo no está aprendiendo la identidad del dispositivo?", "a": "El protocolo usa validación cruzada por evento con exclusión de dispositivo: al retener un evento, las ventanas normales del dispositivo asociado se excluyen del entrenamiento. Además, la normalización se calcula por dispositivo sobre ventanas normales. La confusión de identidad fue un sesgo detectado explícitamente porque inflaba el recall inicial.", "level": "extremo", "crit": false, "idea": "El diseño de partición se alinea con la unidad de potencial fuga."}, {"id": "g53", "deck": "modelos", "q": "¿Qué problema tiene normalizar por dispositivo si un dispositivo opera en múltiples lugares?", "a": "La normalización asume que el contexto del dispositivo es relativamente estable. La tesis identifica que 33.9% opera en dos o más ubicaciones, hasta 23, por lo que ese supuesto es imperfecto. Se declara como limitación y se propone normalización conjunta por dispositivo y ubicación como trabajo futuro.", "level": "extremo", "crit": false, "idea": "Reconocer que la corrección actual resuelve un sesgo, pero deja una fuente residual de heterogeneidad."}, {"id": "g55", "deck": "modelos", "q": "¿Por qué no eliminar directamente los saltos GPS imposibles?", "a": "Un umbral duro requeriría definir qué desplazamiento es físicamente imposible en todos los contextos y podría eliminar datos legítimos si el dispositivo cambia de ubicación o se reasigna. La tesis optó por una transformación robusta que reduce influencia sin introducir otra regla de exclusión difícil de justificar. Se reconoce que una lógica geoespacial más rica sería una mejora futura.", "level": "extremo", "crit": false, "idea": "Preferimos mitigar el impacto antes que inventar una regla universal no sustentada."}, {"id": "g57", "deck": "modelos", "q": "¿La mejora por ensamble no indica que el modelo individual es poco confiable?", "a": "Sí, precisamente. La tesis lo presenta como hallazgo metodológico: una sola semilla no es una estimación estable en este régimen de etiquetas escasas. La respuesta correcta no es ocultarlo, sino usar múltiples inicializaciones y reportar la sensibilidad. En producción, esa inestabilidad sería una razón adicional para no desplegar una única red sin calibración y monitoreo.", "level": "extremo", "crit": false, "idea": "La inestabilidad es un hallazgo, no algo que debamos negar."}, {"id": "g59", "deck": "modelos", "q": "¿Qué diferencia hay entre el score de anomalía del autoencoder y la probabilidad del clasificador?", "a": "El autoencoder produce un error de reconstrucción: una medida de qué tan distinta es una ventana respecto al patrón aprendido como normal, no una probabilidad calibrada de riesgo. El clasificador produce un score/probabilidad discriminativa entrenada con etiquetas. Ambos pueden umbralizarse por percentiles, pero su semántica es distinta.", "level": "extremo", "crit": false, "idea": "Error de reconstrucción ≠ probabilidad de evento."}, {"id": "g60", "deck": "modelos", "q": "¿Están calibradas las probabilidades del clasificador?", "a": "El documento no reporta un procedimiento formal de calibración probabilística como Platt o isotonic. Por ello, las salidas se usan principalmente para ranking y umbralización por percentiles, no para afirmar que “0.8 significa 80% de riesgo”. En un despliegue futuro, calibración y drift deberían formar parte de la validación.", "level": "extremo", "crit": false, "idea": "No atribuir interpretación probabilística absoluta a scores no calibrados."}, {"id": "g62", "deck": "modelos", "q": "¿Elegir la ventana más próxima al evento no favorece artificialmente el modelo?", "a": "Es una decisión conservadora respecto a comparaciones múltiples, pero limita la interpretación temporal: evalúa la señal más cercana al evento y no prueba anticipación prolongada. Por eso el análisis de lead time se reporta aparte y concluye que no hay evidencia de horizonte de horas. Para demostrar predicción temprana se necesitaría definir a priori ventanas anticipadas y evaluarlas temporalmente con más eventos.", "level": "extremo", "crit": false, "idea": "La ventana próxima responde a detección, no demuestra anticipación."}, {"id": "g26", "deck": "estadistica", "q": "¿Por qué priorizaron recall?", "a": "Porque en un problema de riesgo operativo el costo de omitir un evento relevante es alto. El recall cuantifica qué proporción de los eventos disponibles supera el umbral. No se usa solo: se acompaña de falsas alarmas por ventana, intervalos de confianza, pruebas de etiquetas aleatorias y simulación de alertas diarias, para evitar que una sensibilidad alta oculte un costo operativo inaceptable.", "level": "basico", "crit": false, "idea": "Recall es central, pero siempre se interpreta junto con falsos positivos y carga operativa."}, {"id": "g27", "deck": "estadistica", "q": "¿Por qué no usan accuracy como métrica principal?", "a": "Con una prevalencia extremadamente baja, un clasificador que predijera “normal” casi siempre tendría una accuracy aparentemente excelente y sería inútil. Accuracy quedaría dominada por la clase mayoritaria. Por eso se prefieren métricas por clase y evaluación por evento.", "level": "intermedio", "crit": false, "idea": "En desbalance extremo, accuracy puede ser alta aun con cero capacidad útil."}, {"id": "g28", "deck": "estadistica", "q": "¿Por qué el F1 > 0.80 dejó de ser criterio adecuado?", "a": "F1 depende fuertemente de la prevalencia y del balance entre precisión y recall. El criterio inicial provenía de datasets más balanceados y con etiquetado exhaustivo, muy distintos a un evento del orden de uno por mil. Por eso se conserva como referencia histórica, pero la evaluación final enfatiza recall, falsas alarmas y comparación con una distribución nula conservando la prevalencia real.", "level": "intermedio", "crit": false, "idea": "No se “elimina” F1 para favorecer resultados; se reconoce que no es comparable entre prevalencias tan distintas."}, {"id": "g33", "deck": "estadistica", "q": "¿Qué significa p empírico = 0.032 en la prueba de árboles?", "a": "Con 30 repeticiones de la distribución nula, ninguna alcanzó el recall observado de 48.15% en P95. El valor empírico mínimo con 30 repeticiones es 1/(30+1) ≈ 0.032. Esto indica que el resultado observado es incompatible con lo que se vio bajo ese procedimiento nulo, dentro de la resolución limitada por el número de repeticiones.", "level": "intermedio", "crit": false, "idea": "Es evidencia frente al azar bajo el procedimiento definido, no una probabilidad de que la hipótesis sea verdadera."}, {"id": "g29", "deck": "estadistica", "q": "¿Por qué usan percentiles como umbrales?", "a": "Los percentiles fijan tasas de falsa alarma de referencia de forma comparable entre modelos: por ejemplo, P99.9 corresponde aproximadamente a 0.1% de ventanas normales por encima del umbral. Esto evita optimizar el umbral sobre los mismos eventos evaluados y reduce el riesgo de selección oportunista del mejor punto.", "level": "dificil", "crit": false, "idea": "El umbral se define por la distribución de normalidad, no por buscar el máximo resultado en los eventos."}, {"id": "g30", "deck": "estadistica", "q": "¿Qué significa realmente P99.9?", "a": "Que el umbral se ubica en el percentil 99.9 de los puntajes de referencia. Aproximadamente 0.1% de las ventanas normales superarían ese valor por construcción. No significa 99.9% de exactitud ni 99.9% de confianza.\n\nEvitar: Decir que P99.9 significa “99.9% de precisión”.", "level": "dificil", "crit": false, "idea": "Percentil del score normal ≠ accuracy."}, {"id": "g31", "deck": "estadistica", "q": "¿Cómo construyeron los intervalos de confianza?", "a": "Mediante bootstrap de 1,000 réplicas sobre el vector de detecciones de los 54 eventos. El objeto remuestreado es el evento, no las millones de ventanas, porque el evento es la unidad pertinente de evaluación. Eso refleja la incertidumbre derivada del pequeño número efectivo de casos positivos.", "level": "dificil", "crit": false, "idea": "Bootstrap a nivel evento evita una falsa precisión basada en ventanas correlacionadas."}, {"id": "g35", "deck": "estadistica", "q": "¿Por qué el resultado del recurrente no es “significativo” si quedó fuera de las diez permutaciones?", "a": "Porque con 10 repeticiones el p empírico mínimo es 1/11 = 0.091, mayor que 0.05. Que el observado supere todas las repeticiones sugiere señal, pero la cantidad de permutaciones no permite una afirmación de significación convencional. Por eso se usa el término evidencia indicativa.", "level": "dificil", "crit": false, "idea": "Separar evidencia descriptiva de significación formal."}, {"id": "g36", "deck": "estadistica", "q": "¿La superposición de IC prueba que ambos modelos son equivalentes?", "a": "No. La tesis lo aclara expresamente. La superposición indica que con esta muestra no podemos sostener una diferencia concluyente en P99.9, pero una prueba de equivalencia requeriría hipótesis, margen de equivalencia y procedimiento específico. Por eso solo afirmamos ausencia de evidencia concluyente de diferencia.", "level": "dificil", "crit": false, "idea": "No confundir “no diferencia demostrada” con “equivalencia demostrada”."}, {"id": "g38", "deck": "estadistica", "q": "¿Qué es la razón 315 y por qué no es “315 veces mejor que el azar”?", "a": "Es el cociente descriptivo entre recall 31.5% y falsa alarma por ventana 0.1% en P99.9. Sirve para contextualizar separación en baja prevalencia, pero no es una probabilidad, odds ratio, causalidad ni prueba formal frente al azar. La tesis lo limita explícitamente a un indicador descriptivo.", "level": "dificil", "crit": false, "idea": "La comparación formal frente al azar la hace la permutación, no la razón 315."}, {"id": "g41", "deck": "estadistica", "q": "¿Por qué no reportan PR-AUC como métrica principal?", "a": "No fue una métrica principal definida en el protocolo final del documento. Se priorizaron recall por umbral, falsas alarmas, IC, distribución nula y volumen operativo porque permiten traducir el resultado a decisiones concretas. PR-AUC sería una métrica complementaria razonable en desbalance extremo, pero añadirla no sustituiría la evaluación por evento ni el análisis operativo.", "level": "dificil", "crit": false, "idea": "Reconocer que sería complementaria, sin inventar un resultado que la tesis no reporta."}, {"id": "g32", "deck": "estadistica", "q": "¿Es bootstrap válido con solo 54 eventos?", "a": "Es una aproximación útil, pero no elimina la limitación del tamaño muestral. Con 54 eventos los intervalos necesariamente son amplios y la tesis lo reconoce. La finalidad no es fingir precisión, sino cuantificar incertidumbre de manera más informativa que un valor puntual. Una ampliación del histórico debería reducir esa amplitud y permitir validaciones temporales más fuertes.", "level": "extremo", "crit": false, "idea": "El bootstrap cuantifica incertidumbre; no crea información que la muestra no contiene."}, {"id": "g34", "deck": "estadistica", "q": "¿Por qué 30 permutaciones son pocas para una prueba estadística?", "a": "Son suficientes para obtener una resolución mínima de 0.032, pero son modestas. Por eso el documento no pretende estimar un p muy preciso; lo interpreta como evidencia de robustez. Con más capacidad computacional, aumentaría las repeticiones para estimar mejor la cola nula. El contraste recurrente, con 10 repeticiones, se reporta explícitamente solo como evidencia indicativa porque su mínimo p posible es 0.091.", "level": "extremo", "crit": false, "idea": "La tesis no oculta la resolución limitada de la prueba."}, {"id": "g37", "deck": "estadistica", "q": "¿Por qué comparan 31.5% y 38.9% si los IC son tan amplios?", "a": "Porque el objetivo es establecer una línea base y un rango de desempeño bajo un protocolo común, no declarar un ganador absoluto. Los valores puntuales muestran una ventaja descriptiva de árboles y los intervalos expresan la incertidumbre. La simulación operativa agrega otra dimensión: 16.9 vs 15.9 incidentes/día en P99.9, prácticamente equivalentes.", "level": "extremo", "crit": false, "idea": "Se compara para caracterizar, no para sobreafirmar superioridad."}, {"id": "g39", "deck": "estadistica", "q": "Explique matemáticamente el sesgo de comparaciones múltiples de 77.4%.", "a": "Si cada ventana tuviera 5% de probabilidad de superar un umbral P95 por azar y se permiten aproximadamente 29 intentos por evento, la probabilidad de al menos un cruce es 1-(1-0.05)^29 = 1-0.95^29 ≈ 0.774. El recall aparente de 81.48% estaba muy cerca de ese valor. Al reducir a una sola ventana por evento, se elimina esa ventaja artificial.", "level": "extremo", "crit": false, "idea": "Múltiples oportunidades de acertar por azar convierten el evento en una lotería con muchos intentos."}, {"id": "g40", "deck": "estadistica", "q": "¿Por qué conservar la prevalencia original en evaluación?", "a": "Porque remuestrear la evaluación cambiaría artificialmente la relación entre positivos y negativos y alteraría métricas dependientes de prevalencia. El entrenamiento puede usar estrategias como muestreo ponderado para que el modelo vea positivos, pero la evaluación debe aproximar el escenario real. Esa separación entre entrenamiento y evaluación es crucial.", "level": "extremo", "crit": false, "idea": "Se puede balancear el aprendizaje; no se debe balancear artificialmente la realidad evaluada."}, {"id": "g42", "deck": "estadistica", "q": "¿El p=0.032 es vulnerable a haber escogido P95 después de ver resultados?", "a": "Sí, si P95 se hubiera seleccionado exclusivamente porque produjo el menor p, existiría riesgo de selección múltiple. La defensa correcta es que el estudio reporta múltiples umbrales y usa P95 para el contraste de robustez del modelo de comparación, mientras que P99.9 se discute como punto operativo más exigente. No debemos presentar p=0.032 como una prueba universal de todos los umbrales, sino como evidencia bajo ese punto específico.", "level": "extremo", "crit": false, "idea": "No generalizar un p de un umbral a toda la curva de desempeño."}, {"id": "g76", "deck": "negocio", "q": "¿Qué valor de negocio tiene el modelo?", "a": "El valor potencial está en priorizar atención operativa y detectar patrones de riesgo sin depender exclusivamente de una activación humana. Pero la tesis no afirma un ROI ya demostrado. El resultado actual es una línea base que permite estimar carga de alertas y decidir si la infraestructura está suficientemente madura para un piloto.", "level": "basico", "crit": false, "idea": "Valor potencial y evidencia de producción son cosas distintas."}, {"id": "g88", "deck": "negocio", "q": "¿Qué entienden por riesgo operativo en este estudio?", "a": "La posibilidad de que el comportamiento, la condición o la situación de un agente en servicio derive en un evento que comprometa su integridad, la del servicio o la del cliente. Es una definición acotada al recurso humano en seguridad privada y operacionalizada mediante juicio de expertos.", "level": "basico", "crit": false, "idea": "El constructo es específico al estudio y no una definición universal de riesgo operacional corporativo."}, {"id": "c5.1", "deck": "negocio", "q": "En términsimples, ¿qué logra su modelo?", "a": "Detecta aproximadamente uno de cada tres incidentes de riesgo, generando unas 17 alertas diarias para una flota de cientos de dispositivos. Comparado con revisar al azar, es del orden de 300 veces más eficiente. No anticipa con horas de margen: señala en tiempo casi real.", "level": "intermedio", "crit": false}, {"id": "c5.3", "deck": "negocio", "q": "¿Cuánto costaría implementar esto?", "a": "No lo evaluamos; está fuera del alcance del trabajo y no tenemos una estimación defendible. Lo que sí podemos precisar es qué habilitaría la inversión con mayor retorno: unificar los tres esquemas de codificación de personal. Esa única intervención haría construibles seis de las diez variables que hoy no lo son, todas validadas por juicio experto. Es una intervención de integración de datos, no de infraestructura tecnológica.", "level": "intermedio", "crit": false}, {"id": "c5.5", "deck": "negocio", "q": "¿Qué pasa con los dos tercios de eventos que no detecta?", "a": "Siguen dependiendo del mecanismo actual: el reporte del agente. El modelo no reemplaza ese canal, se suma a él. Y aquí hay un matiz importante: el valor potencialmente mayor está justamente en los casos donde el agente no puede o no reporta, sea por incapacidad o por práctica establecida. Pero no podemos aportar evidencia empírica sobre el desempeño en esos casos, porque nuestra fuente de verdad es precisamente el registro formal. Lo declaramos como hipótesis operativa derivada del hallazgo cualitativo, no como resultado.", "level": "intermedio", "crit": false}, {"id": "c5.7", "deck": "negocio", "q": "¿Cómo evitan que esto se convierta en vigilancia sobre los trabajadores?", "a": "Es una preocupación que abordamos en la sección de consideraciones éticas. Tres decisiones concretas: los datos se seudonimizaron antes de cualquier análisis, con tablas de correspondencia separadas; la unidad de análisis es el dispositivo y el turno, no la persona, lo que en este caso es consecuencia de la propia estructura de los datos; y declaramos explícitamente que el modelo no debe emplearse de forma autónoma para decisiones disciplinarias. En un eventual despliegue, el propósito legítimo es la priorización preventiva de atención, no el control individual.", "level": "intermedio", "crit": false}, {"id": "c6.1", "deck": "negocio", "q": "¿Por qué el sector de seguridad privada?", "a": "Por tres razones. Es un sector con exposición ocupacional alta y creciente, en un contexto de aumento de incidentes en zonas portuarias y logísticas. Genera de forma continua datos operacionales que no se aprovechan analíticamente. Y no existía un instrumento validado que operacionalizara el riesgo operativo de este personal en el contexto latinoamericano, pese a haber desarrollos equivalentes para otras ocupaciones expuestas.", "level": "intermedio", "crit": false}, {"id": "c6.2", "deck": "negocio", "q": "¿Sus resultados se pueden extender a otras empresas del sector?", "a": "No sin validación adicional, y lo declaramos como limitación. El estudio se desarrolla sobre una única organización, con sus propios sistemas, prácticas de registro y contexto operativo, y los siete jueces provienen de ella. Extender el instrumento requeriría replicación con paneles independientes. Lo que sí es potencialmente transferible es el método: el protocolo de evaluación y el diagnóstico de operacionalización son aplicables a cualquier organización con estructura de datos similar.", "level": "intermedio", "crit": false}, {"id": "g77", "deck": "negocio", "q": "¿Cuál de los dos modelos supervisados elegiría hoy para un piloto?", "a": "No elegiría automáticamente por el recall puntual. En P99.9, árboles tiene 38.9% vs 31.5% del recurrente y 15.9 vs 16.9 alertas/día, pero los intervalos se superponen y no hay prueba formal de diferencia. Por simplicidad, estabilidad y explicabilidad, el ensamble de árboles sería una opción razonable para un piloto controlado, siempre que antes se mejore la infraestructura de datos y se mantenga supervisión humana.", "level": "intermedio", "crit": false, "idea": "En producción, simplicidad y gobernabilidad pesan junto con la métrica."}, {"id": "g82", "deck": "negocio", "q": "¿Qué proceso de negocio cambiaría primero?", "a": "La gobernanza de identificadores y el registro de incidentes. Sin vínculo agente-turno y dispositivo-servicio se pierden variables críticas; sin categorías de incidentes estandarizadas la etiqueta sigue siendo pobre. Ambas mejoras tienen efecto transversal incluso si la empresa decide no desplegar ML.", "level": "intermedio", "crit": false, "idea": "Los cambios recomendados crean valor de datos más allá del modelo."}, {"id": "g87", "deck": "negocio", "q": "¿Por qué el ensamble de árboles puede ser preferible desde negocio?", "a": "Tiene desempeño descriptivamente superior en varios umbrales, menor sensibilidad a inicialización y es más sencillo de entrenar, explicar y operar que una red recurrente ensamblada. Sin embargo, la tesis no demuestra superioridad concluyente en P99.9; la elección final debe considerar mantenibilidad, explicabilidad y evolución de datos.", "level": "intermedio", "crit": false, "idea": "No escoger tecnología por moda; escoger por desempeño + operación."}, {"id": "g89", "deck": "negocio", "q": "¿Cómo eligieron las 14 variables?", "a": "Se partió del análisis de fuentes, literatura y conocimiento operativo, y luego las 14 variables fueron sometidas a juicio de siete expertos en pertinencia y claridad. El proceso no asumió que todas fueran válidas o construibles: de hecho, algunas no superaron los criterios de pertinencia y varias no pudieron operacionalizarse por limitaciones de integración.", "level": "intermedio", "crit": false, "idea": "Proponer variables y validarlas son etapas diferentes."}, {"id": "c5.2", "deck": "negocio", "q": "¿Un 31% de detección justifica invertir en esto?", "a": "Depende de con qué se compare, y ahí está el punto. Hoy la detección depende de que el agente active el botón de emergencia; no existe ningún mecanismo automático. La comparación relevante no es contra un 100% ideal sino contra la ausencia de detección automática. Y la cifra que importa operativamente no es el 31%, es la razón entre detección y falsa alarma: en el umbral operativo es de aproximadamente 315 a 1. Dicho con franqueza: como sistema autónomo no es suficiente. Como capa de apoyo a una central de monitoreo que hoy no tiene ninguna, sí aporta.", "level": "dificil", "crit": true}, {"id": "c5.4", "deck": "negocio", "q": "¿Diecisiete alertas diarias son manejables para una central de monitoreo?", "a": "Es el único umbral que lo es, y por eso lo elegimos como punto de operación. Los umbrales inferiores generan volúmenes de cientos a más de mil incidentes diarios, incompatibles con cualquier respuesta efectiva. Diecisiete alertas para el conjunto de la flota equivalen a menos de una por hora, que es un volumen atendible. Es importante señalar que ese punto de operación no lo elegimos por maximizar una métrica, sino por viabilidad operativa.", "level": "dificil", "crit": true}, {"id": "c5.6", "deck": "negocio", "q": "¿Recomiendan que la empresa implemente esto ya?", "a": "No como sistema de decisión. Nuestra recomendación tiene un orden. Primero, resolver la trazabilidad entre fuentes: es la condición previa para todo lo demás. Segundo, ampliar el período de datos, que multiplicaría los eventos disponibles y reduciría la incertidumbre de las estimaciones. Tercero, recién entonces evaluar un despliegue piloto como capa de apoyo, nunca como mecanismo automático de decisión sobre personas. El documento es explícito en que el modelo no debe usarse de forma autónoma como fundamento de decisiones disciplinarias o de terminación laboral.", "level": "dificil", "crit": true}, {"id": "c6.3", "deck": "negocio", "q": "Los expertos mencionan un código encubierto por radio. ¿No invalida eso toda su etiqueta?", "a": "No la invalida, la sitúa. Significa que nuestra etiqueta —la activación del mecanismo formal de emergencia— subestima la ocurrencia real del fenómeno, en una magnitud que no podemos cuantificar. Tiene dos consecuencias que declaramos. Primero, sobre validez de constructo: hay distancia entre el riesgo operativo como concepto amplio y la variable observada. Segundo, y más relevante: el valor de un detector automático reside precisamente en los casos que el canal formal no captura, y sobre esos casos no podemos aportar evidencia porque nuestra fuente de verdad es ese mismo canal. Es una limitación estructural del diseño, no un defecto de ejecución.", "level": "dificil", "crit": true}, {"id": "g78", "deck": "negocio", "q": "¿16 alertas al día son muchas o pocas?", "a": "La tesis no define un SLA corporativo, por lo que no puede afirmar universalmente que sea aceptable. Lo que sí muestra es la escala: P95 generaría cientos de alertas diarias y P99.9 reduce la carga a alrededor de 16. La decisión final debe incorporar capacidad de la central, costo de revisión y costo de omisión.", "level": "dificil", "crit": false, "idea": "El umbral operativo es una decisión costo-beneficio, no solo estadística."}, {"id": "g79", "deck": "negocio", "q": "¿Por qué no optimizaron directamente una función económica de costo?", "a": "Porque no se disponía de una matriz de costos confiable para falsos positivos, falsos negativos e intervenciones. Inventarla habría agregado supuestos de negocio no validados. Se prefirió presentar la frontera recall–alertas para que la organización pueda incorporar sus costos reales en una etapa de piloto.", "level": "dificil", "crit": false, "idea": "Primero medir técnicamente; luego calibrar con costos reales del negocio."}, {"id": "g83", "deck": "negocio", "q": "¿Cómo evitar que el sistema se convierta en una herramienta disciplinaria?", "a": "La tesis establece que debe ser apoyo preventivo, nunca decisión automática. Cualquier alerta debe pasar por revisión humana, y las salidas no deberían usarse como fundamento autónomo para sanciones, asignación perjudicial o terminación laboral. En un piloto, se debe definir explícitamente el propósito, accesos, retención y usos prohibidos.", "level": "dificil", "crit": false, "idea": "Governance by design: propósito preventivo y humano en el circuito."}, {"id": "g85", "deck": "negocio", "q": "¿Cuál es el roadmap de implementación recomendado?", "a": "1) corregir claves agente-turno y dispositivo-servicio; 2) limpiar GPS y formalizar incidentes, incluyendo riesgos reportados por radio; 3) ampliar histórico; 4) reentrenar y revalidar con partición temporal; 5) incorporar texto y revalidar; 6) ejecutar piloto shadow sin decisiones automáticas; 7) calibrar umbral según capacidad operativa y costos.", "level": "dificil", "crit": false, "idea": "Datos → validación → shadow pilot → decisión operativa."}, {"id": "g90", "deck": "negocio", "q": "¿Qué variables tuvieron respaldo sólido en pertinencia?", "a": "Cuatro: cobertura GPS efectiva del turno (V01), permanencia en zona asignada (V02), meses de antigüedad en la empresa (V09) y puestos distintos/rotación (V11). Lo crítico es que solo V01 pudo construirse con los sistemas actuales, lo cual sustenta la conclusión de que la infraestructura limita la medición.", "level": "dificil", "crit": false, "idea": "4 sólidas, solo 1 construible."}, {"id": "g91", "deck": "negocio", "q": "¿Por qué “longitud de novedades” fue cuestionada?", "a": "Porque los expertos indicaron que la cantidad de texto no equivale a severidad ni relevancia. Una descripción corta puede ser crítica y una larga puede ser rutinaria. Por eso se propone reemplazar longitud por análisis de contenido o categoría, lo que justifica la futura modalidad NLP.", "level": "dificil", "crit": false, "idea": "Cantidad de palabras no es un proxy válido de severidad."}, {"id": "g93", "deck": "negocio", "q": "¿Por qué la antigüedad puede tener una relación no lineal o incluso inversa con riesgo?", "a": "Los expertos señalaron que mucha permanencia en un servicio puede reflejar experiencia, pero también generar familiaridad excesiva o posibilidades de colusión; y la aparente mayor incidencia en personal nuevo puede deberse a estilos de reporte o asignación. Por eso no asumimos causalidad lineal a partir de un patrón descriptivo.", "level": "dificil", "crit": false, "idea": "Las variables humanas requieren interpretación contextual; correlación aparente no equivale a riesgo causal."}, {"id": "g95", "deck": "negocio", "q": "¿Qué aportó cualitativamente la triangulación que no podía aportar el modelo?", "a": "Explicó el subregistro de riesgos, cuestionó proxies débiles como longitud de texto, reveló heterogeneidad del rol de supervisor y mostró que algunos patrones de antigüedad o novedades podían ser artefactos de proceso. Sin esa triangulación, una correlación podría haberse interpretado erróneamente como causal o predictiva.", "level": "dificil", "crit": false, "idea": "El dominio ayuda a distinguir señal real de artefacto organizacional."}, {"id": "g97", "deck": "negocio", "q": "¿Qué significa “significativa” y “sólida” en su validación?", "a": "Se considera significativa cuando el límite inferior del IC al 90% supera el valor de azar de la escala, 0.50. Se considera sólida cuando el límite inferior del IC al 95% alcanza 0.70. Son dos niveles distintos: evidencia por encima del azar y respaldo sustantivo más exigente.", "level": "dificil", "crit": false, "idea": "No confundir V puntual alto con certeza; la decisión usa límites inferiores."}, {"id": "c5.8", "deck": "negocio", "q": "¿Qué le dirían a la empresa si les pregunta por qué invirtió en esto y obtuvo un 31%?", "a": "Que el entregable no es el 31%. Son tres cosas: un instrumento validado que define qué debe medirse para gestionar el riesgo operativo, un diagnóstico documentado de que sus sistemas actuales permiten medir solo tres de esas catorce variables, y un protocolo de evaluación que permite medir el progreso futuro sin sobreestimarlo. El 31% es la línea base contra la cual medir cualquier mejora posterior. Y el diagnóstico tiene valor inmediato: identifica exactamente qué intervención de integración de datos habilita seis variables más.", "level": "extremo", "crit": false}, {"id": "c5.9", "deck": "negocio", "q": "Si la empresa hubiera contratado a un proveedor comercial, ¿habría obtenido un mejor resultado?", "a": "Probablemente habría obtenido un número reportado mejor. Nuestro propio trabajo muestra cómo: sin corregir la confusión de identidad y las comparaciones múltiples, este mismo conjunto de datos produce un 81%. Ese número es reproducible y es falso. Un proveedor sin incentivo para auditar su propia evaluación reportaría algo de ese orden. La contribución de este trabajo incluye haber cuantificado esa brecha en un dominio donde no existía evidencia previa.", "level": "extremo", "crit": false}, {"id": "c6.4", "deck": "negocio", "q": "¿No debieron construir una etiqueta mejor a partir de las entrevistas?", "a": "Lo consideramos y lo descartamos. Construir una etiqueta a partir de nuestra propia interpretación de las entrevistas habría introducido circularidad: el modelo aprendería a detectar lo que nosotros suponemos que distingue un evento de riesgo, y la evaluación mediría el acuerdo con nuestras suposiciones, no con la realidad. Por la misma razón descartamos generar datos sintéticos para ampliar el número de eventos. La recomendación que sí hacemos a la organización es formalizar y unificar las categorías de incidente, que hoy se emplean de manera no estandarizada, y considerar el registro de las situaciones comunicadas por códigos encubiertos.", "level": "extremo", "crit": false}, {"id": "g80", "deck": "negocio", "q": "Si el modelo detecta solo 38.9% en P99.9, ¿por qué una empresa pagaría por él?", "a": "No proponemos comprarlo como producto terminado. El 38.9% es una línea base con información limitada y un umbral de baja carga. Su mayor valor hoy es demostrar que existe señal y revelar qué mejoras de datos pueden elevar el techo. Un despliegue prematuro sería injustificable; una inversión en integración de datos sí está respaldada por el estudio.", "level": "extremo", "crit": false, "idea": "La recomendación empresarial principal es invertir en medición antes que en despliegue masivo."}, {"id": "g81", "deck": "negocio", "q": "¿Qué KPI usaría en un piloto real?", "a": "Al menos: recall por evento, alertas revisadas por día, precisión de alertas confirmadas, tiempo de anticipación, tiempo de respuesta del operador, tasa de alertas por dispositivo/servicio, drift del score y tasa de cobertura de datos. También mediría consecuencias operativas, pero sin atribuir causalidad al modelo hasta diseñar una evaluación prospectiva.", "level": "extremo", "crit": false, "idea": "Un piloto debe medir desempeño técnico, carga humana y calidad de datos."}, {"id": "g84", "deck": "negocio", "q": "¿Qué pasa si un gerente insiste en usar el score para rankear “agentes riesgosos”?", "a": "La respuesta sería que el modelo no está validado para inferir una propiedad estable del agente. La unidad modelada está fuertemente ligada a dispositivo, turno y contexto, y además no existe un vínculo agente-dispositivo confiable. Convertir el score en ranking individual sería una extrapolación metodológica y ética no respaldada por la tesis.", "level": "extremo", "crit": false, "idea": "Score de ventana ≠ perfil permanente de una persona."}, {"id": "g86", "deck": "negocio", "q": "¿Dónde está el ROI cuantificado?", "a": "No está cuantificado y no debemos inventarlo. La tesis no mide reducción de pérdidas ni accidentes en producción. Sí entrega insumos para calcularlo posteriormente: volumen esperado de alertas por umbral, señal detectable y acciones de infraestructura necesarias. Un ROI riguroso requeriría costos reales de incidentes, revisión e intervención y un piloto prospectivo.", "level": "extremo", "crit": false, "idea": "No prometer ROI que el estudio no midió."}, {"id": "g92", "deck": "negocio", "q": "¿Cómo afecta el código encubierto de radio a la validez del modelo?", "a": "Implica subregistro de la clase positiva. Algunas situaciones de riesgo se comunican sin activar la emergencia formal, por lo que el “ground truth” corporativo no contiene todos los eventos reales. El modelo puede penalizarse por alertar antes de algo que no aparece como etiqueta o aprender una definición incompleta del riesgo. Es una amenaza de validez de constructo.", "level": "extremo", "crit": false, "idea": "La etiqueta formal subestima el fenómeno real."}, {"id": "g94", "deck": "negocio", "q": "¿El panel de expertos de una sola empresa invalida el instrumento?", "a": "No lo invalida, pero restringe su validez externa. El instrumento tiene validez de contenido documentada para ese contexto. No lo presentamos como estándar sectorial. Para generalizarlo sería necesario repetir la validación con paneles independientes, otras empresas y posiblemente otros países.", "level": "extremo", "crit": false, "idea": "Validez contextual sí; estandarización sectorial no."}, {"id": "g96", "deck": "negocio", "q": "¿Por qué usar V de Aiken y no simplemente porcentaje de acuerdo?", "a": "V de Aiken incorpora la posición de las valoraciones dentro de una escala ordinal y permite estimar un coeficiente entre 0 y 1. La tesis además utiliza intervalos score para considerar incertidumbre, en vez de depender de un porcentaje o valor puntual. Esto es especialmente importante con siete jueces.", "level": "extremo", "crit": false, "idea": "Se evalúa validez de contenido con incertidumbre, no solo acuerdo bruto."}, {"id": "g98", "deck": "etica", "q": "¿Qué riesgo ético principal presenta el proyecto?", "a": "Que un score de riesgo aplicado a trabajadores pueda convertirse en vigilancia excesiva o en base para decisiones disciplinarias injustas. Por eso la tesis limita el uso a apoyo preventivo, exige supervisión humana y rechaza decisiones automáticas sobre sanciones o terminación laboral.", "level": "basico", "crit": false, "idea": "El modelo es apoyo a la decisión, no juez del trabajador."}, {"id": "g99", "deck": "etica", "q": "¿Qué datos personales trata el estudio?", "a": "Principalmente geolocalización y patrones operativos vinculables potencialmente a trabajadores, por lo que se requieren medidas de protección. El estudio utiliza seudonimización para análisis y restringe la publicación de información identificable.", "level": "intermedio", "crit": false, "idea": "La geolocalización laboral puede ser sensible por su capacidad de perfilar conducta."}, {"id": "g100", "deck": "etica", "q": "¿Anonimización y seudonimización son lo mismo?", "a": "No. La seudonimización reemplaza identificadores manteniendo una correspondencia controlada, de modo que el análisis entre fuentes siga siendo posible. La anonimización pretende impedir la reidentificación de manera irreversible o razonablemente irreversible. En el pipeline analítico hablamos de seudonimización; para publicaciones se busca no exponer información identificable.", "level": "dificil", "crit": false, "idea": "Usar la terminología correcta según posibilidad de reidentificación."}, {"id": "g102", "deck": "etica", "q": "¿Cómo evitar sesgo contra ciertos grupos de trabajadores?", "a": "Antes de producción se requieren auditorías de equidad por grupos relevantes, análisis de desempeño diferencial, monitoreo de drift y mecanismos de mitigación. La tesis declara que fairness no formó parte del alcance experimental, por lo que no afirma ausencia de sesgo demográfico.", "level": "dificil", "crit": false, "idea": "No afirmar fairness si no fue medido."}, {"id": "g104", "deck": "etica", "q": "¿Qué explicabilidad debería ofrecerse?", "a": "Para un piloto, se debería poder explicar qué variables y patrones contribuyen al score, qué incertidumbre existe y qué limitaciones del dato aplican. Un modelo de árboles facilita explicabilidad local/global; una red recurrente requeriría técnicas adicionales. En ningún caso una explicación debe transformarse en acusación causal sobre el trabajador.", "level": "dificil", "crit": false, "idea": "Explicar la predicción sin convertir asociación en culpa."}, {"id": "g106", "deck": "etica", "q": "¿Qué leyes peruanas son relevantes según la tesis?", "a": "La Ley 29733 de Protección de Datos Personales, la Ley 29783 de Seguridad y Salud en el Trabajo y la Ley 31814 sobre promoción del uso de IA, además del marco de seguridad privada. La defensa debe centrarse en principios: finalidad, proporcionalidad, seguridad, privacidad, transparencia y responsabilidad.", "level": "dificil", "crit": false, "idea": "Citar las normas solo cuando estén vinculadas a un principio concreto."}, {"id": "g101", "deck": "etica", "q": "¿Puede un empleado realmente consentir libremente el uso de GPS en una relación laboral asimétrica?", "a": "El consentimiento en contexto laboral puede estar condicionado por la relación de poder, por lo que no debería ser la única base de legitimidad. La tesis se centra en el marco peruano y en uso preventivo; una implementación real requeriría revisión legal de base de tratamiento, proporcionalidad, finalidad, información al trabajador, minimización y derechos de acceso/oposición según corresponda.", "level": "extremo", "crit": false, "idea": "No reducir toda legitimidad a “firmó un consentimiento”."}, {"id": "g103", "deck": "etica", "q": "¿La exclusión de variables protegidas elimina discriminación?", "a": "No. Variables aparentemente neutrales como ubicación, turno o servicio pueden actuar como proxies. La única defensa responsable es evaluar resultados por grupos y revisar impactos. Además, como el estudio no dispone de vínculos completos con la persona, ni siquiera sería metodológicamente válido atribuir riesgos individuales permanentes.", "level": "extremo", "crit": false, "idea": "Fairness requiere auditoría de resultados, no solo remover columnas."}, {"id": "g105", "deck": "etica", "q": "¿Qué harían si el modelo reduce incidentes pero aumenta vigilancia y presión laboral?", "a": "Ese trade-off no puede decidirlo solo la métrica. Se debe evaluar proporcionalidad, impacto sobre derechos, participación de áreas de seguridad y recursos humanos, y mecanismos de revisión. La tesis se alinea con un uso preventivo y humano; una mejora de seguridad no justificaría automáticamente un sistema invasivo sin límites.", "level": "extremo", "crit": false, "idea": "Optimización técnica no sustituye juicio ético y legal."}, {"id": "g107", "deck": "etica", "q": "¿Puede la empresa usar el modelo para despedir a alguien si siempre obtiene scores altos?", "a": "La tesis explícitamente lo desaconseja y no lo valida para ese uso. Un score de ventana no prueba conducta ilícita, causalidad ni riesgo intrínseco del agente. Usarlo como fundamento autónomo para sanción o despido sería una extrapolación técnica y ética no soportada.", "level": "extremo", "crit": false, "idea": "Nunca presentar score como evidencia individual de culpabilidad."}, {"id": "c7.1", "deck": "hostiles", "q": "Su título original decía \"detección temprana\" y \"análisis multimodal\". ¿Por qué cambió?", "a": "Porque los resultados no sostenían ninguno de los dos términos. La modalidad textual no resultó incorporable en esta etapa, de modo que el componente multimodal quedó fuera de verificación empírica, y el régimen temporal alcanzado es de detección casi simultánea, no anticipada. Ajustar el título fue una decisión deliberada de coherencia: preferimos un título que describa lo que el trabajo demuestra antes que uno que prometa lo que el trabajo no verificó. El diseño multimodal original está documentado en el capítulo de metodología y su no implementación explicada en resultados.", "level": "dificil", "crit": true}, {"id": "c7.2", "deck": "hostiles", "q": "Entonces no cumplieron con su hipótesis. ¿Qué justifica aprobar este trabajo?", "a": "La hipótesis inicial no se verificó en dos de sus tres componentes, y el documento lo dice sin rodeos. Lo que sí se sostiene es la afirmación derivada que orientó la reformulación del criterio: el modelo alcanza una capacidad de detección significativamente superior a la esperable por asignación aleatoria, con un valor de probabilidad empírico de 0.032 para el modelo con mayor respaldo estadístico.\n\nY hay una respuesta más de fondo. La contribución de este trabajo no es el modelo final. Es haber establecido empíricamente por qué el problema no se resuelve hoy: no por limitación de los algoritmos, sino por la trazabilidad entre las fuentes de información. Diez de catorce variables validadas por expertos resultan inconstruibles, incluida una que obtuvo consenso unánime del panel. Ese diagnóstico, el instrumento validado y el protocolo de evaluación que cuantifica los sesgos son entregables verificables, y ninguno de los tres dependía de que la hipótesis original se cumpliera.", "level": "extremo", "crit": true}, {"id": "c7.3", "deck": "hostiles", "q": "¿No es cómodo declarar que la limitación es de la empresa y no de su trabajo?", "a": "Sería cómodo si no estuviera demostrado. La demostración es específica: 6 coincidencias sobre 211,424 y 4,362 registros entre dos esquemas de codificación de personal, verificable en las fuentes. Y no atribuimos todas las limitaciones a la organización: declaramos nueve, y varias son nuestras. El período de datos limitado es una limitación del diseño de la investigación, no del dominio, porque existe un archivo histórico que no solicitamos. La vinculación de eventos por línea telefónica es una decisión nuestra con riesgo declarado. El número de repeticiones de la prueba de etiquetas aleatorias limita nuestras propias afirmaciones. La distribución de responsabilidad está explícita.", "level": "extremo", "crit": false}, {"id": "c7.4", "deck": "hostiles", "q": "Documentan varios errores propios. ¿Eso no es un problema de calidad del trabajo?", "a": "Es lo contrario, y es una decisión deliberada. Los errores que documentamos —la confusión de identidad, las comparaciones múltiples, la inconsistencia en el análisis temporal— no aparecen en el documento porque no supimos ocultarlos, sino porque el proceso que los detectó y corrigió es parte del aporte. La secuencia de 72% a 81% y finalmente a 48.15% es reproducible: cualquiera que trabaje este problema sin controlar esos sesgos obtendrá el número inflado. Cuantificar esa brecha en un dominio sin evidencia previa tiene valor metodológico. Un trabajo que reportara únicamente el resultado final sería más limpio de leer y menos útil.", "level": "extremo", "crit": false}, {"id": "c7.5", "deck": "hostiles", "q": "¿Qué harían distinto si empezaran de nuevo?", "a": "Cuatro cosas concretas. Solicitaríamos el archivo histórico completo desde el inicio, que es la restricción de fondo del estudio. Auditaríamos el protocolo de evaluación antes de reportar cualquier resultado, en lugar de descubrir los sesgos por sospecha sobre cifras altas. Usaríamos una escala de cuatro niveles en el instrumento de validación, para eliminar la posición intermedia. Y verificaríamos la integrabilidad de las fuentes antes de comprometer un diseño multimodal, en lugar de descubrir la imposibilidad durante la ejecución.", "level": "extremo", "crit": true}, {"id": "c7.6", "deck": "hostiles", "q": "Si tuvieran que resumir el trabajo en una frase que no oculte nada, ¿cuál sería?", "a": "Establecimos que los datos de geolocalización de esta organización contienen señal de riesgo operativo detectable por encima del azar, que su aprovechamiento está limitado hoy por la integración de las fuentes y no por los algoritmos, y que medir ese desempeño sin sobreestimarlo requiere controlar cinco sesgos que, sin corregir, inflan el resultado en más de treinta puntos porcentuales.", "level": "extremo", "crit": false}, {"id": "g108", "deck": "hostiles", "q": "¿No es su muestra de 54 eventos demasiado pequeña para una tesis de Data Science?", "a": "Es pequeña para estimar con precisión y lo reconocemos como la principal fuente de incertidumbre, pero no invalida todo el estudio. Precisamente por eso usamos intervalos, exclusión por dispositivo, evaluación por evento, pruebas nulas y lenguaje prudente. Además, el trabajo no se limita a estimar un recall: identifica por qué de 2,447 eventos solo 54 son observables con GPS, lo cual es un hallazgo de infraestructura.\n\nEvitar: Responder “54 es suficiente” sin matices.", "level": "extremo", "crit": false, "idea": "La limitación de muestra es parte del resultado sobre observabilidad."}, {"id": "g109", "deck": "hostiles", "q": "¿Por qué debería creer que esos 54 eventos no fueron escogidos porque daban mejor resultado?", "a": "Porque el criterio de inclusión es trazabilidad: estar dentro del período GPS y tener cobertura confirmada del dispositivo. De 2,447, 301 caen en el período y 54 cumplen cobertura. La tesis reconoce que no son aleatorios ni intercambiables con el universo, pero no fueron seleccionados por score o desempeño.", "level": "extremo", "crit": false, "idea": "Selección por disponibilidad de medición, no por resultado del modelo."}, {"id": "g110", "deck": "hostiles", "q": "¿No hay HARKing al reformular la hipótesis después de ver los datos?", "a": "Para evitar esa interpretación, la tesis conserva explícitamente el planteamiento inicial como referencia y dice que el contraste de detectabilidad es complementario, no sustituto. El F1>0.80 y las 24 horas siguen evaluándose y no se verifican. El contraste adicional pregunta algo más básico: si existe señal superior al azar con la modalidad efectivamente disponible.", "level": "extremo", "crit": false, "idea": "No ocultamos el planteamiento inicial ni lo reescribimos como si siempre hubiera sido otro."}, {"id": "g111", "deck": "hostiles", "q": "¿Cómo puede decir “señal predictiva” si p=0.032 se obtiene con solo 30 permutaciones?", "a": "Lo decimos con el alcance exacto: el ensamble de árboles supera las 30 realizaciones nulas en P95 y el p empírico mínimo es 0.032. Es evidencia bajo ese procedimiento, no una prueba definitiva de generalización. El recurrente se reporta todavía más cautelosamente como indicativo. La validación externa queda pendiente.", "level": "extremo", "crit": false, "idea": "Usar lenguaje calibrado: evidencia, no certeza universal."}, {"id": "g112", "deck": "hostiles", "q": "Si las etiquetas están subregistradas, ¿no hace inválidas todas las métricas?", "a": "Las métricas son válidas respecto a la etiqueta observable utilizada, pero no necesariamente respecto al constructo completo de riesgo. Por eso la tesis separa validez de medición de validez de constructo y declara el subregistro. Un modelo puede detectar patrones que preceden riesgos no etiquetados y contarlos como falsos positivos. Eso limita la interpretación, no obliga a fingir que la etiqueta es perfecta.", "level": "extremo", "crit": false, "idea": "Métrica válida para el proxy; generalización al constructo real es limitada."}, {"id": "g113", "deck": "hostiles", "q": "¿Por qué no resolvieron el problema de datos antes de entrenar modelos?", "a": "Porque demostrar qué relaciones faltaban y cuánto limitaban la operacionalización era uno de los objetivos. No teníamos autoridad para rediseñar los sistemas corporativos durante la tesis. Se reconstruyó y validó todo lo posible y se documentó exactamente qué cambios habilitarían cada variable.", "level": "extremo", "crit": false, "idea": "La tesis diagnostica y cuantifica la brecha; no puede modificar retrospectivamente sistemas fuente."}, {"id": "g114", "deck": "hostiles", "q": "¿No es una contradicción decir que el algoritmo no es el cuello de botella y luego comparar modelos?", "a": "No. La comparación establece una línea base y demuestra que cambiar de arquitectura produce diferencias menores que las limitaciones de medición y evaluación. Sin esa comparación, la afirmación de que el cuello de botella está en datos sería más especulativa. Los árboles y recurrente convergen a un rango parecido en P99.9 y ambos trabajan con un subconjunto pobre de las variables validadas.", "level": "extremo", "crit": false, "idea": "Comparar modelos ayuda a demostrar que el límite no se resuelve solo con más complejidad."}, {"id": "g115", "deck": "hostiles", "q": "¿Por qué no hacer un estudio causal en lugar de predictivo?", "a": "Porque no hay intervención ni asignación aleatoria y el objetivo empresarial es detección, no estimar el efecto causal de una exposición. Además, muchas variables candidatas no están operacionalizadas. Un estudio causal requeriría un DAG, confusores medidos y diseño distinto. La tesis evita atribuir causalidad a las asociaciones aprendidas.", "level": "extremo", "crit": false, "idea": "No responder una pregunta causal con datos observacionales incompletos."}, {"id": "g116", "deck": "hostiles", "q": "¿El hecho de que 51 de 54 ventanas estén dentro de ±15 minutos no indica simplemente detección simultánea, no predicción?", "a": "Sí. Esa es precisamente la interpretación prudente de la tesis. El modelo muestra discriminación asociada al entorno temporal del evento, pero no evidencia de anticipación de horas. Por eso el título final habla de detección y el trabajo futuro propone ampliar histórico y evaluar señal anticipatoria de forma específica.", "level": "extremo", "crit": false, "idea": "No vender detección contemporánea como predicción temprana."}, {"id": "g117", "deck": "hostiles", "q": "¿Por qué la ventana de evaluación más cercana al evento no introduce leakage temporal si incluye datos posteriores?", "a": "La defensa depende de cómo se construye la ventana respecto al timestamp. El documento caracteriza la alineación y encuentra algunas ventanas hasta 6.33 minutos posteriores. Por tanto, no debemos afirmar que todas las ventanas son estrictamente pre-evento. Justamente esa es la razón por la que no sostenemos anticipación y tratamos este análisis como detección alrededor del evento. Para un sistema prospectivo se requeriría restringir ventanas a datos disponibles antes del instante de decisión.", "level": "extremo", "crit": false, "idea": "Reconocer el límite temporal en lugar de afirmar causalidad/previsión que no está garantizada."}, {"id": "g118", "deck": "hostiles", "q": "¿Entonces el modelo podría estar usando información posterior al evento?", "a": "En una fracción de ventanas, la alineación temporal puede quedar hasta pocos minutos después del timestamp del incidente. El estudio lo reporta y no usa esos resultados para afirmar anticipación. La siguiente validación debería imponer una política estricta de corte temporal pre-evento y evaluar lead times definidos a priori.", "level": "extremo", "crit": false, "idea": "Es una limitación de detección temporal, no algo que deba ocultarse."}, {"id": "g119", "deck": "hostiles", "q": "¿No deberían invalidar entonces la palabra “predictivo”?", "a": "No necesariamente, porque el modelo predice una etiqueta sobre ventanas no vistas, pero sí obliga a delimitar el sentido operativo: actualmente demuestra discriminación/detección alrededor del evento, no un sistema de alerta temprana. Por esa razón el título se corrigió de “detección temprana” a “detección de eventos”.", "level": "extremo", "crit": false, "idea": "Predictivo en ML, pero no anticipatorio en horas."}, {"id": "g120", "deck": "hostiles", "q": "¿Por qué usar una banda de exclusión de ±4 horas alrededor de eventos para normalidad?", "a": "Para evitar contaminar el aprendizaje de normalidad con observaciones cercanas a un incidente, donde podría existir señal relacionada aun si no están etiquetadas exactamente como evento. Es una decisión conservadora que reduce riesgo de leakage de clase. Su anchura es un supuesto metodológico y podría ser sometida a análisis de sensibilidad con más datos.", "level": "extremo", "crit": false, "idea": "La banda protege la referencia normal; no se presenta como ley universal."}, {"id": "g121", "deck": "hostiles", "q": "¿No produce la normalización por dispositivo una fuga si usa datos futuros del mismo dispositivo?", "a": "El protocolo indica que la normalización se calcula únicamente con ventanas normales y en validación por evento se excluye el dispositivo retenido del entrenamiento. En la simulación temporal, debe mantenerse el principio de calcular transformaciones con información de entrenamiento. La tesis diseña el protocolo para evitar que estadísticas del evento retenido contaminen el entrenamiento.", "level": "extremo", "crit": false, "idea": "Toda transformación debe aprenderse en entrenamiento, no en test."}, {"id": "g122", "deck": "hostiles", "q": "¿Por qué el recall del árbol subió de 72.22% a 81.48% después de una corrección si las correcciones deberían bajar sesgo?", "a": "Porque no todas las correcciones tienen efecto monotónico. La exclusión por dispositivo y normalización alteraron la representación y pueden mejorar separación legítima aun mientras corrigen confusión. Lo importante es que una revisión posterior identificó comparaciones múltiples, cuya corrección redujo el desempeño a 48.15%. La secuencia muestra por qué no se debe asumir que cualquier mejora después de “limpiar” es automáticamente real.", "level": "extremo", "crit": false, "idea": "Auditar iterativamente; el signo del cambio no determina si una corrección es válida."}, {"id": "g123", "deck": "hostiles", "q": "¿Cómo diferencia “falsa alarma” de una alerta correcta no registrada por subregistro?", "a": "No podemos diferenciarla completamente con la etiqueta actual. Por eso hablamos de falsa alarma respecto al registro formal, no necesariamente respecto al riesgo real. En producción se necesitaría un proceso de adjudicación humana de alertas y una etiqueta enriquecida para estimar precisión clínica/operativa real.", "level": "extremo", "crit": false, "idea": "Falso positivo respecto al dataset puede ser evento no etiquetado."}, {"id": "g124", "deck": "hostiles", "q": "¿Qué resultado de su tesis sería el primero que intentaría falsar en una réplica?", "a": "La existencia y magnitud de señal superior al azar en geolocalización. La replicaría con un histórico más largo, más eventos, partición temporal estricta y otra organización. Si esa señal persiste bajo el mismo protocolo, la evidencia de generalización aumentaría; si desaparece, se demostraría que la línea base era contextualmente específica.", "level": "extremo", "crit": false, "idea": "Una buena contribución debe ser falsable y replicable."}, {"id": "g125", "deck": "hostiles", "q": "¿Cuál es la amenaza más peligrosa que todavía podría hacer que su desempeño sea optimista?", "a": "La representatividad de los 54 eventos y la atribución indirecta evento-dispositivo mediante número de línea, además del contexto multiubicación de los dispositivos. También la etiqueta incompleta. Son limitaciones explícitas y por eso no proponemos despliegue productivo.", "level": "extremo", "crit": false, "idea": "El protocolo corrige cinco sesgos, pero no elimina toda incertidumbre de datos."}, {"id": "g126", "deck": "hostiles", "q": "Si repitieran la tesis desde cero, ¿qué cambiarían?", "a": "Primero aseguraríamos diseño de datos antes de modelar: vínculo agente-turno y dispositivo-servicio, histórico GPS más largo, taxonomía de incidentes, registro de eventos por radio y trazabilidad temporal estricta. Luego preregistraríamos criterios de evaluación y ejecutaríamos un holdout temporal externo. Finalmente incorporaríamos texto solo después de validar la línea base unimodal.", "level": "extremo", "crit": false, "idea": "Diseñar la medición antes del algoritmo."}, {"id": "g127", "deck": "hostiles", "q": "¿Cuál es el mayor error que un lector podría cometer al interpretar su tesis?", "a": "Pensar que 38.9% es una “probabilidad de que ocurra un incidente” o que el modelo anticipa casi 40% de incidentes con horas de ventaja. En realidad es recall de eventos bajo un umbral P99.9, con ventanas cercanas al timestamp y sin evidencia de horizonte de horas.", "level": "extremo", "crit": false, "idea": "Siempre definir métrica, unidad y horizonte."}, {"id": "f1", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“Demostramos que el modelo multimodal no funciona.”", "a": "“La formulación multimodal no pudo contrastarse en su totalidad; con geolocalización no se verificaron los criterios de 24 horas ni F1 > 0.80.”", "level": "basico", "crit": false}, {"id": "f2", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“El modelo predice incidentes 40% de las veces.”", "a": "“En P99.9, el ensamble de árboles alcanzó recall de 38.9% sobre los eventos evaluables, sin evidencia de anticipación de horas.”", "level": "basico", "crit": false}, {"id": "f3", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“Los dos modelos son equivalentes.”", "a": "“No encontramos evidencia concluyente de diferencia en P99.9; la superposición de intervalos no prueba equivalencia.”", "level": "basico", "crit": false}, {"id": "f4", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“Tenemos significancia en ambos modelos.”", "a": "“Árboles mostró p empírico 0.032; en recurrente, con 10 repeticiones, el mínimo posible fue 0.091 y se reporta como evidencia indicativa.”", "level": "basico", "crit": false}, {"id": "f5", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“54 eventos son suficientes.”", "a": "“54 eventos permiten una línea base con incertidumbre explícita; la escasez limita precisión y generalización y se declara como limitación.”", "level": "basico", "crit": false}, {"id": "f6", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“Los falsos positivos son errores del modelo.”", "a": "“Son falsos positivos respecto a la etiqueta formal; el subregistro impide descartar que algunos correspondan a riesgos no registrados.”", "level": "basico", "crit": false}, {"id": "f7", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“La IA va a reducir accidentes.”", "a": "“Ese impacto es una expectativa de aplicación; no fue medido en este estudio.”", "level": "basico", "crit": false}, {"id": "f8", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“El deep learning es mejor.”", "a": "“La complejidad no mostró ventaja concluyente; en este régimen, árboles fue competitivo y más estable.”", "level": "basico", "crit": false}, {"id": "f9", "deck": "frases", "q": "En la sustentación, ¿cómo decir mejor esto?\n\n“El score identifica agentes riesgosos.”", "a": "“El score se refiere a ventanas/dispositivos/contexto y no valida un atributo permanente de la persona.”", "level": "basico", "crit": false}], "tips": {"cierre": "“Nuestra investigación comenzó con una expectativa ambiciosa: detectar riesgo operativo mediante un diseño multimodal y con anticipación prolongada. La evidencia real nos obligó a ser más rigurosos. De 14 variables validadas, solo tres pudieron construirse completamente; de 2,447 eventos corporativos, solo 54 tuvieron cobertura GPS confirmada. Al auditar la evaluación identificamos cinco sesgos capaces de inflar el desempeño, incluyendo un efecto de comparaciones múltiples que por sí solo generaba una probabilidad de cruce por azar cercana al 77%. Después de corregirlos, encontramos señal superior al azar, pero no evidencia de anticipación con horizonte de horas. Por ello, nuestra contribución no es prometer un sistema listo para producción, sino entregar un instrumento de medición, una línea base honesta y un protocolo que permite a La Empresa mejorar su infraestructura y medir futuros avances sin autoengañarse con métricas infladas.”", "dinamica": "Cuando una pregunta sea muy técnica, un integrante responde el núcleo y otro complementa solo si agrega valor. Eviten tres respuestas distintas a la misma pregunta. Si no recuerdan un decimal, es preferible decir “aproximadamente” y explicar la dirección del resultado que inventar una cifra. Si el jurado identifica una limitación real, reconocerla y explicar cómo está controlada o propuesta como trabajo futuro suele ser más sólido que intentar negarla.."}};
